// ~/usr/code/ai/claude/specs/daimond_rating_u2_plan_20260930.md.
//
// THE RATED TILE NEVER CHANGES. The arrows, the chip row and the Rating tile are
// chrome (`data-chrome`) set beside the answer, and a rating is appended to the end
// of the chat as a `rating_log` message; no message already there is edited. Nothing
// here calls `touchChat`, so a rating is not a turn and does not move its chat up the
// rail. Nothing is stored beyond the message itself: the lit state is worked out from
// the transcript and the burst each time it is drawn.
var _rateBurst = new Map();		// chat id -> the ratings not yet committed
var _rateTimer = new Map();		// chat id -> the timer that commits them
var _rateFormMemo = null;

/// The rating form from the engine, or null where the build's wasm is too old to
/// name one (the arrows then do not appear, and nothing else notices).
function rateForm() {
	if (_rateFormMemo) return _rateFormMemo;
	try { _rateFormMemo = DaimondRatings.form(Wasm.rating_form()); }
	catch (e) { _rateFormMemo = null; }
	return _rateFormMemo;
}

function rateProdOf(m) {
	var p = (window.DaimondProvenance && m) ? DaimondProvenance.of(m)[0] : null;
	return p && p.k === 'answer' ? p : null;
}

/// Can this stored message be rated? A final answer that carries its record: not a
/// streamed row, not a paused or interrupted partial, not an empty placeholder.
function rateQualifies(m) {
	return !!m && m.role === 'assistant' && !!m.mid && typeof m.content === 'string'
		&& !!m.content.trim() && !m.provisional && !m.why && !!rateProdOf(m);
}

function rateChatOf(id) {
	if (pg.current && pg.current.id === id) return pg.current;
	return pg.chats.find(function (c) { return c.id === id; }) || null;
}

/// Is a turn running in this chat? A burst waits for it: a rating never lands
/// among a turn's own messages.
function rateInFlight(chat) {
	if (!chat) return false;
	if (chat._generating) return true;
	var ms = chat.messages || [];
	for (var i = 0; i < ms.length; i++) {
		var m = ms[i];
		if (!m) continue;
		if (m.provisional) return true;
		if (m.interrupted && m.why === 'dispatched' && !(m.content && String(m.content).trim())) return true;
	}
	return false;
}

function rateBurstFor(id) {
	var b = _rateBurst.get(id);
	if (!b) { b = DaimondRatings.createBurst(); _rateBurst.set(id, b); }
	return b;
}

function rateMsgById(msgs, mid) {
	for (var i = msgs.length - 1; i >= 0; i--) {
		var m = msgs[i];
		if (m && m.role === 'assistant' && String(m.mid) === String(mid)) return m;
	}
	return null;
}

/// The stored answer behind a tile on screen, its record and the form; null when it
/// cannot be rated. Matched on the tile's `data-mid` in the chat on screen, never on
/// `prod.c`, which is a daimon's conversation and not the tile.
function rateTarget(tile) {
	var form = rateForm();
	if (!form || !pg.current || !tile) return null;
	// A file row of a changed-files note: its record is looked up in the transcript by the row's
	// handle, as an answer's is by its `data-mid`, and there is no message of its own (`m` null).
	if (tile.classList.contains('turn-file-row')) {
		var fp = tile.dataset.h ? rateFileRecs().get(tile.dataset.h) : null;
		return fp ? { m: null, prod: fp, form: form } : null;
	}
	if (!tile.dataset.mid) return null;
	var m = rateMsgById(pg.current.messages || [], tile.dataset.mid);
	return rateQualifies(m) ? { m: m, prod: rateProdOf(m), form: form } : null;
}

/// The records of every changed-files row in the chat on screen, by handle. The notes are
/// the user messages that carry `prod` (a Diamond's tail note), and a chat's `files_log`.
function rateFileRecs() {
	var out = new Map(), msgs = (pg.current && pg.current.messages) || [];
	if (!window.DaimondProvenance) return out;
	for (var i = 0; i < msgs.length; i++) {
		var m = msgs[i];
		if (!m || (m.role !== 'user' && m.role !== 'files_log') || !Array.isArray(m.prod)) continue;
		DaimondProvenance.of(m).forEach(function (p) { if (p.k === 'file') out.set(p.h, p); });
	}
	return out;
}

function rateCtx(chat, g) {
	// A file's bytes are pinned by its `hash`, so it holds no tool path and no length (`build`).
	var file = g.prod.k === 'file';
	return {
		head:  DaimondRatings.headRaw(chat.messages, g.prod.h),
		prod:  g.prod,
		tools: file ? '' : DaimondRatings.toolsOf(chat.messages, g.prod, g.m.mid),
		len:   file ? 0 : DaimondProvenance.lenOf(g.m.content),
		form:  g.form.form,
	};
}

function rateTap(tile, sign) {
	var g = rateTarget(tile);
	if (!g) return;
	DaimondRatings.tap(rateBurstFor(pg.current.id), rateCtx(pg.current, g), g.prod.h, sign);
	rateArm(pg.current.id);
	mountRateControls();
}

function rateChip(tile, id) {
	var g = rateTarget(tile), b = pg.current ? _rateBurst.get(pg.current.id) : null;
	if (!g || !b || !DaimondRatings.toggleTag(b, g.prod.h, id)) return;
	rateArm(pg.current.id);
	mountRateControls();
}

// ── When a burst commits ───────────────────────────────────

/// (Re)start the quiet a burst waits for. The timer polls while a turn runs, so
/// however the turn ends the burst is written as soon as the chat is free.
function rateArm(id) {
	var old = _rateTimer.get(id);
	if (old) clearTimeout(old);
	_rateTimer.delete(id);
	var b = _rateBurst.get(id);
	if (!b || !b.drafts.size) return;
	var wait = Math.max(0, b.last + DaimondRatings.BURST_MS - Date.now()) + 40;
	_rateTimer.set(id, setTimeout(function () { rateFire(id); }, wait));
}

function rateFire(id) {
	_rateTimer.delete(id);
	var b = _rateBurst.get(id), chat = rateChatOf(id);
	if (!b || !b.drafts.size) return;
	if (!chat) { _rateBurst.delete(id); return; }
	if (rateInFlight(chat)) { _rateTimer.set(id, setTimeout(function () { rateFire(id); }, 1000)); return; }
	if (DaimondRatings.due(b, Date.now(), false)) commitRatings(id, {});
	else rateArm(id);
}

/// Write a chat's burst now: `take` the messages, append them to the chat, and
/// draw them as one tile if the chat is on screen. Refused while a turn runs.
/// `o.draw === false` writes without drawing, for a chat about to be left.
function commitRatings(id, o) {
	o = o || {};
	var b = _rateBurst.get(id), chat = rateChatOf(id);
	if (!b || !b.drafts.size) return false;
	if (!chat) { _rateBurst.delete(id); return false; }
	if (rateInFlight(chat)) return false;
	var tm = _rateTimer.get(id);
	if (tm) { clearTimeout(tm); _rateTimer.delete(id); }
	// Made past the chat's last message (`tsPast`, as a person's message is), so a rating from a clock that runs behind the
	// device that made the question still sorts after it, and is told on the next message from any device.
	var list = DaimondRatings.take(b, tsPast(chat, Date.now()));
	_rateBurst.delete(id);
	if (list.length) {
		list.forEach(function (m) { chat.messages.push(m); });
		persistChats();		// and no touchChat: a rating is not a turn
		ratingsDigestSoon();
	}
	if (pg.current === chat && o.draw !== false) {
		if (list.length) rateDraw(chat, list);
		mountRateControls();
	}
	return list.length > 0;
}

// ── The ratings of the whole account (Rating U5b) ───────────────────
//
// `ratingsAccount` rolls every rating in every chat into the cells the Optimiser's digest and
// the Models page read (`DaimondRatingRoll`, ratingroll.js; plan daimond_optimiser_532_plan_
// 20261004.md §5 U5b). It is a pure function of the transcripts: nothing is stored, no chat is
// made resident and nothing is written to the store, so a rebuild from cold equals one from the
// memo, byte for byte (J1, J2).
//
// A chat that is not resident is read ONE AT A TIME through `ChatStore.readMessages`, the reader
// the collect streams its transcripts through (`collectChatsRefs`) without its two heals: it leaves the
// summary mirror, the chunks and the legacy row alone, and the transcript is released before the next,
// so the peak is a single chat however
// many there are. The read itself yields to the page between chats. A resident chat is read
// from memory, where its newest rating can be ahead of the store. Only the reduced part
// (`chatPart`) is kept, in a memo keyed on the summary row's `seed`, `msgCount` and `standing`,
// so a chat whose transcript moved is read again and no other is. The store is read SETTLED, as
// the collect reads it (F-1): a save queued behind a write in flight has already put its new
// seed in the mirror, and a read made now would pair that seed with the old transcript for good.
var _ratingsMemo  = new Map();		// chat id -> { key, part }, for each stored chat read from the store
var _ratingsRun   = null;			// the rebuild in flight, which a caller arriving meanwhile shares
var _ratingsAgain = false;			// such a caller wants one more pass, so it sees what changed after it asked
var _ratingsTimer = 0;				// the digest write that follows a burst of ratings
var RATINGS_DIGEST_MS = 10000;
var MODEL_COUNTS_KEY  = 'daimond-model-ratings';		// the Models page's old thumbs counts; nothing writes it now

/// What a stored chat's memo is valid for: the three figures of its summary row that move
/// with its transcript. Empty where the row carries no seed, which is never memoised.
function ratingsKey(sum) {
	return sum && sum.seed ? sum.seed + '|' + (sum.msgCount | 0) + '|' + (sum.standing || '') : '';
}

async function ratingsWalk() {
	try { await ChatStore.booted(); } catch (e) { /* the store reads empty, and so does the roll */ }
	try { await ChatStore.settled(); } catch (e) { /* the alarm is up; the read is what there is */ }
	var mem = {};
	pg.chats.forEach(function (c) { if (c && c.id) mem[c.id] = c; });
	var sums = storedChats(), parts = [], live = {}, reads = 0;
	for (var i = 0; i < sums.length; i++) {
		var sum = sums[i], id = sum.id, held = mem[id], part;
		live[id] = 1;
		if (held && held._loaded && Array.isArray(held.messages)) {
			part = DaimondRatingRoll.chatPart(held.messages);
		} else {
			var key = ratingsKey(sum), hit = key ? _ratingsMemo.get(id) : null;
			if (hit && hit.key === key) {
				part = hit.part;
			} else {
				var got = await ChatStore.readMessages(id);
				reads++;
				part = DaimondRatingRoll.chatPart(got.messages || []);
				got = null;							// released before the next chat
				if (key) _ratingsMemo.set(id, { key: key, part: part });
				else _ratingsMemo.delete(id);
			}
		}
		parts.push(part);
	}
	Array.from(_ratingsMemo.keys()).forEach(function (id) { if (!live[id]) _ratingsMemo.delete(id); });
	var form = rateForm();
	return { roll: DaimondRatingRoll.cells(parts, { sides: form ? form.tags : null }), parts: parts, reads: reads, chats: sums.length };
}

/// The account's rating cells, as `{ roll, parts, reads, chats }`: `roll` from `DaimondRatingRoll.cells`,
/// `parts` the chat parts it was rolled from (the Compare grid reads their `turns`),
/// `reads` the transcripts this pass read from the store (none when every chat's memo stood).
/// Callers that arrive while a pass is running share it, and get a further pass if they
/// asked after it began.
function ratingsAccount() {
	if (_ratingsRun) { _ratingsAgain = true; return _ratingsRun; }
	_ratingsRun = (async function () {
		try {
			var out;
			do { _ratingsAgain = false; out = await ratingsWalk(); } while (_ratingsAgain);
			return out;
		} finally { _ratingsRun = null; _ratingsAgain = false; }
	})();
	return _ratingsRun;
}

/// The digest's tail: the Ratings section, then the closing block of the old Models-page
/// counts kept in `models-before.md`. A part that cannot be made is left out and the rest stands.
async function ratingsDigest() {
	var out = '';
	try {
		var acct = await ratingsAccount();
		out += '\n' + DaimondRatingRoll.digestText(acct.roll, (pg.diamonds || []).map(function (d) {
			return { id: d.id, name: d.name };
		}));
	} catch (e) { /* no Ratings section this time; the next write tries again */ }
	try {
		var before = String(await Wasm.store_read(USAGE_DIR + '/models-before.md') || '');
		if (before.trim()) out += '\n' + before.replace(/\s+$/, '') + '\n';
	} catch (e) { /* none was imported */ }
	return out;
}

/// Write the digest soon, once a burst of ratings has stopped: a rating is not a turn, so
/// nothing else would write it. Each call restarts the wait.
function ratingsDigestSoon() {
	if (_ratingsTimer) clearTimeout(_ratingsTimer);
	_ratingsTimer = setTimeout(function () {
		_ratingsTimer = 0;
		try { writeUsageDigest(); } catch (e) { /* best-effort */ }
	}, RATINGS_DIGEST_MS);
}

/// Move the Models page's old thumbs counts (O4) to where they belong, once: written as the
/// closing block of the Optimiser's digest, kept as that block's source in
/// `system/usage/models-before.md` (app state, never synced), and the key removed. The block is
/// never mixed into a figure. The key goes only once the file holds it, so a store that is not
/// there yet leaves it for the next digest; with nothing in it, it just goes.
async function importModelCounts() {
	var raw;
	try { raw = localStorage.getItem(MODEL_COUNTS_KEY); } catch (e) { return; }
	if (raw === null || raw === undefined || !window.DaimondRatingRoll) return;
	var list = DaimondRatingRoll.legacy(raw);
	if (list.length) {
		try { await Wasm.store_write(USAGE_DIR + '/models-before.md', DaimondRatingRoll.beforeText(list)); }
		catch (e) { return; }
	}
	try { localStorage.removeItem(MODEL_COUNTS_KEY); } catch (e) { /* the file already holds the counts */ }
}
