	return pushUserRecord(chat, { role: 'user', content: (t && t.userText) || '', mid: iturn, iturn: iturn, ts: (t && +t.at) || nowTs() },
		meta.app !== true, typeof meta.pre === 'string' ? meta.pre : '');
