// ── The controls on an answer ──────────────────────────────

function rateButton(cls, svg, aria) {
	var b = document.createElement('button');
	b.type = 'button'; b.className = cls; b.innerHTML = svg;
	b.setAttribute('aria-label', aria); b.title = aria;
	return b;
}

/// One group: up, down, details. An answer wears it in a row under its text, on every
/// device (UNBLOCK-10); a changed-files row wears it at its right end.
function rateGroup() {
	var g = document.createElement('span');
	g.className = 'ctile-rate'; g.dataset.chrome = 'rate';
	g.setAttribute('role', 'group'); g.setAttribute('aria-label', t('rating.aria_group'));
	var up = rateButton('ctile-rate-up', RATE_UP_SVG, t('rating.aria_up'));
	up.setAttribute('aria-pressed', 'false');
	var dn = rateButton('ctile-rate-down', RATE_DOWN_SVG, t('rating.aria_down'));
	dn.setAttribute('aria-pressed', 'false');
	var mo = rateButton('ctile-rate-more', RATE_MORE_SVG, t('rating.aria_more'));
	mo.setAttribute('aria-haspopup', 'dialog');
	g.appendChild(up); g.appendChild(dn); g.appendChild(mo);
	return g;
}

function rateSet(el, name, val) { if (el.getAttribute(name) !== val) el.setAttribute(name, val); }

/// Put the rating row and (for a pending down rating) a chip row on one answer tile,
/// and set what is lit. Idempotent; it touches only chrome, never the tile's own markup.
function rateDress(tile, g, head, burst) {
	var body = tile._body;
	var row = tile.querySelector(':scope > .ctile-rate-row');
	if (!row) {
		row = document.createElement('div');
		row.className = 'ctile-rate-row'; row.dataset.chrome = 'rate';
		row.appendChild(rateGroup());
		body.after(row);
	}
	var st = DaimondRatings.stateWith(head, burst, g.prod.h);
	tile.querySelectorAll('.ctile-rate').forEach(function (grp) { rateLight(grp, st); });
	var d = burst && burst.drafts ? burst.drafts.get(g.prod.h) : null;
	rateDressTags(tile.querySelector(':scope > .ctile-rate-tags'), row, g.form, d && !d.clear && d.s < 0 ? d : null, 'answer');
}

/// Set what a group shows: the lit arrow, and whether details hold more than a bare arrow.
function rateLight(grp, st) {
	rateSet(grp.querySelector('.ctile-rate-up'), 'aria-pressed', st.lit === 'up' ? 'true' : 'false');
	rateSet(grp.querySelector('.ctile-rate-down'), 'aria-pressed', st.lit === 'down' ? 'true' : 'false');
	grp.querySelector('.ctile-rate-more').classList.toggle('on', !!st.detail);
}

/// The chip row of a pending down rating, set after `anchor`; `tags` is the one already
/// there or null, and it is removed when there is no draft. Answers the row now standing.
function rateDressTags(tags, anchor, form, draft, kind) {
	if (!draft) { if (tags) tags.remove(); return null; }
	var ids = form.quickFor(kind, 'down');		// the quick row; Details lists every reason
	if (tags && tags.dataset.ids !== ids.join(',')) { tags.remove(); tags = null; }
	if (!tags) {
		tags = document.createElement('div');
		tags.className = 'tile-dlg-seg ctile-rate-tags'; tags.dataset.chrome = 'rate';
		tags.dataset.ids = ids.join(',');
		tags.setAttribute('role', 'group'); tags.setAttribute('aria-label', t('rating.tags_down'));
		ids.forEach(function (id) {
			var b = document.createElement('button');
			b.type = 'button'; b.className = 'tile-dlg-level'; b.dataset.tag = id;
			b.textContent = rateTagWord(form, id);
			b.setAttribute('aria-pressed', 'false');
			tags.appendChild(b);
		});
		anchor.after(tags);
	}
	tags.querySelectorAll('.tile-dlg-level').forEach(function (b) {
		rateSet(b, 'aria-pressed', draft.tags.indexOf(b.dataset.tag) >= 0 ? 'true' : 'false');
	});
	return tags;
}

/// Bring every answer on screen into step with the transcript and the burst: mount the
/// group where an answer qualifies, refresh what is lit, and sweep it off any tile that
/// no longer does. Runs from `renderHistoryFurniture` and wherever a turn ends.
function mountRateControls() {
	if (!chatOutput || !pg.current || !window.DaimondRatings || !window.DaimondProvenance) return;
	var form = rateForm(), msgs = pg.current.messages || [], keep = new Set();
	if (form) {
		var byMid = new Map();
		for (var i = 0; i < msgs.length; i++) {
			var m = msgs[i];
			if (m && m.role === 'assistant' && m.mid) byMid.set(String(m.mid), m);
		}
		var idx = DaimondRatings.index(msgs), burst = _rateBurst.get(pg.current.id) || null;
		chatOutput.querySelectorAll('.ctile.chat-msg-assistant[data-mid]').forEach(function (tile) {
			var msg = byMid.get(tile.dataset.mid);
			if (!rateQualifies(msg) || !tile._lbl) return;
			var g = { m: msg, prod: rateProdOf(msg), form: form };
			keep.add(tile);
			rateDress(tile, g, idx.get(g.prod.h) || null, burst);
		});
	}
	chatOutput.querySelectorAll('.ctile-rate, .ctile-rate-row, .ctile-rate-tags').forEach(function (n) {
		if (n.closest('.turn-files')) return;		// a changed-files row's own, kept by `mountFileRates`
		var tile = n.closest('.ctile');
		if (!tile || !keep.has(tile)) n.remove();
	});
	mountFileRates(chatOutput);
}

/// Put a group on each changed-files row that has a record, light it from the transcript and
/// the burst, and (for a pending down rating) set the chip row after the row. A row with no
/// record gets none, and one that lost its record loses it. Idempotent, and chrome only: the
/// row's own markup, `data-h` included, is built with the row.
function mountFileRates(root) {
	if (!root || !pg.current || !window.DaimondRatings || !window.DaimondProvenance) return;
	var form = rateForm(), msgs = pg.current.messages || [];
	var recs = form ? rateFileRecs() : new Map();
	var idx = form ? DaimondRatings.index(msgs) : null, burst = _rateBurst.get(pg.current.id) || null;
	root.querySelectorAll('.turn-file-row').forEach(function (row) {
		var h = row.dataset.h || '', prod = h ? recs.get(h) : null;
		var grp = row.querySelector(':scope > .turn-file-rate'), nx = row.nextElementSibling;
		var tags = nx && nx.classList.contains('ctile-rate-tags') ? nx : null;
		if (!prod) {
			if (grp) grp.remove();
			if (tags) tags.remove();
			return;
		}
		if (!grp) {
			grp = rateGroup();
			grp.classList.add('turn-file-rate');
			grp.setAttribute('aria-label', t('rating.aria_group_file'));
			var de = row.querySelector(':scope > .turn-file-delta');
			if (de) de.after(grp); else row.appendChild(grp);
		}
		rateLight(grp, DaimondRatings.stateWith(idx.get(h) || null, burst, h));
		var d = burst && burst.drafts ? burst.drafts.get(h) : null;
		rateDressTags(tags, row, form, d && !d.clear && d.s < 0 ? d : null, 'file');
	});
}

/// What a control rates: its changed-files row (a group inside it, or the chip row standing
/// right after it), else its answer's tile.
function rateHostOf(b) {
	var row = b.closest('.turn-file-row');
	if (row) return row;
	var tags = b.closest('.ctile-rate-tags');
	if (tags && tags.closest('.turn-files')) {
		var prev = tags.previousElementSibling;
		return prev && prev.classList.contains('turn-file-row') ? prev : null;
	}
	return b.closest('.ctile');
}
// page-split: install 55

// ── The rating popup ───────────────────────────────────────

function rateSnap(st) {
	return JSON.stringify({ s: st.s, tags: st.tags.slice().sort(), dims: st.dims, note: st.note });
}

/// The details control's popup: five steps, tags, and a collapsed Details holding four
/// dimensions and the person's own words. Nothing is written while it is open. Closing it
/// (the cross, Escape, the backdrop) sets ONE draft into the burst, which commits as a tap's
/// does; Clear sets a withdrawal and closes. It starts from the pending draft, else the head,
/// else empty. The words are held in `st`, so nothing is read from a body that has gone.
function openRatePopup(tile, opener) {
	var g = rateTarget(tile);
	if (!g) return;
	var chat = pg.current, h = g.prod.h, form = g.form, kind = g.prod.k === 'file' ? 'file' : 'answer';
	var burst = _rateBurst.get(chat.id), pend = burst ? burst.drafts.get(h) : null;
	var head = DaimondRatings.headRaw(chat.messages, h);
	var live = head && !head.rating.clear ? head.rating : null;
	var from = pend ? (pend.clear ? null : pend) : live;
	var st = { s: from ? from.s : null, tags: from ? from.tags.slice() : [], dims: {}, note: from ? String(from.note || '') : '' };
	form.dims.forEach(function (d) {
		var v = from && from.dims ? from.dims[d.id] : -1;
		st.dims[d.id] = (typeof v === 'number' && v >= 0 && v <= d.max) ? v : -1;
	});
	var st0 = rateSnap(st), cleared = false;

	var body = document.createElement('div');
	body.className = 'rate-body';

	// The five steps, in words. Pressing the pressed one leaves the choice as it was.
	body.appendChild(secHead(t('rating.sec_score')));
	var scale = document.createElement('div');
	scale.className = 'tile-dlg-seg rate-scale';
	scale.setAttribute('role', 'group'); scale.setAttribute('aria-label', t('rating.sec_score'));
	form.scale.forEach(function (sc) {
		var b = document.createElement('button');
		b.type = 'button'; b.className = 'tile-dlg-level'; b.dataset.s = String(sc.s);
		// The word in a span of its own, so it can ellipsise without clipping the
		// button's tap overlay.
		var word = document.createElement('span');
		word.className = 'rate-step-word'; word.textContent = t(sc.key);
		b.appendChild(word);
		b.setAttribute('aria-pressed', 'false');
		b.addEventListener('click', function () {
			var next = Number(b.dataset.s);
			var was = st.s === null ? 0 : Math.sign(st.s), now = Math.sign(next);
			if (was !== now && was !== 0 && now !== 0) st.tags = [];
			else if (now < 0) st.tags = st.tags.filter(function (id) { return form.tagsFor(kind, 'down').indexOf(id) >= 0; });
			else if (now > 0) st.tags = st.tags.filter(function (id) { return form.tagsFor(kind, 'up').indexOf(id) >= 0; });
			st.s = next;
			paint();
		});
		scale.appendChild(b);
	});
	body.appendChild(scale);

	// Tags for the side chosen: down for a minus, up for a plus, both (down first) for 0.
	var tagHost = document.createElement('div');
	tagHost.className = 'rate-tagbox';
	body.appendChild(tagHost);

	// Details: what a reader looks up rather than what they came to change.
	var adv = advancedBox();
	adv.querySelector('summary').textContent = t('rating.details');
	adv.open = form.dims.some(function (d) { return st.dims[d.id] >= 0; }) || !!st.note;
	form.dims.forEach(function (d) {
		var row = document.createElement('div');
		row.className = 'tile-dlg-field rate-dim';
		var lab = document.createElement('span');
		lab.className = 'tile-dlg-label'; lab.textContent = t(d.key);
		var seg = document.createElement('div');
		seg.className = 'tile-dlg-seg';
		seg.setAttribute('role', 'group'); seg.setAttribute('aria-label', t(d.key));
		for (var v = 0; v <= d.max; v++) (function (v) {
			var b = document.createElement('button');
			b.type = 'button'; b.className = 'tile-dlg-level'; b.dataset.v = String(v);
			b.textContent = String(v);
			b.setAttribute('aria-pressed', st.dims[d.id] === v ? 'true' : 'false');
			b.addEventListener('click', function () {
				st.dims[d.id] = st.dims[d.id] === v ? -1 : v;
				seg.querySelectorAll('.tile-dlg-level').forEach(function (x) {
					x.setAttribute('aria-pressed', st.dims[d.id] === Number(x.dataset.v) ? 'true' : 'false');
				});
			});
			seg.appendChild(b);
		})(v);
		row.appendChild(lab); row.appendChild(seg);
		adv.appendChild(row);
	});
	var noteId = 'rate-said-' + (++_tileDlgSeq);
	var noteLab = document.createElement('label');
	noteLab.className = 'tile-dlg-label rate-said-label'; noteLab.htmlFor = noteId;
	noteLab.textContent = t('rating.note_label');
	var ta = document.createElement('textarea');
	ta.id = noteId; ta.className = 'rate-said-input'; ta.rows = 3; ta.value = st.note;
	var grow = function () { ta.style.height = 'auto'; ta.style.height = ta.scrollHeight + 'px'; };
	ta.addEventListener('input', function () { st.note = ta.value; grow(); });
	adv.appendChild(noteLab); adv.appendChild(ta);
	adv.addEventListener('toggle', function () { if (adv.open) grow(); });
	body.appendChild(adv);

	// Where it goes, and nothing that is not yet true of it.
	var where = document.createElement('div');
	where.className = 'tile-dlg-note rate-where';
	var mdl = g.prod.cm || g.prod.m || '';
	where.textContent = t('rating.where');
	if (mdl) {
		// "Model: <name>" is one unbreakable unit (it never leaves the name alone on a line), and a long name ends in an ellipsis.
		var wm = document.createElement('span');
		wm.className = 'rate-model'; wm.textContent = t('rating.model', { model: mdl }); wm.title = wm.textContent;
		where.appendChild(document.createTextNode(' ')); where.appendChild(wm);
	}
	body.appendChild(where);

	var clearBtn = null;
	if (live) {
		var acts = document.createElement('div');
		acts.className = 'tile-dlg-actions';
		clearBtn = document.createElement('button');
		clearBtn.type = 'button'; clearBtn.className = 'rate-clear tile-keep';
		clearBtn.textContent = t('rating.clear');
		acts.appendChild(clearBtn);
		body.appendChild(acts);
	}

	function paint() {
		scale.querySelectorAll('.tile-dlg-level').forEach(function (b) {
			b.setAttribute('aria-pressed', st.s !== null && Number(b.dataset.s) === st.s ? 'true' : 'false');
		});
		var ids = [];
		if (st.s !== null && st.s <= 0) ids = ids.concat(form.tagsFor(kind, 'down'));
		if (st.s !== null && st.s >= 0) ids = ids.concat(form.tagsFor(kind, 'up'));
		var key = ids.join(',');
		if (tagHost.dataset.ids !== key) {
			tagHost.dataset.ids = key;
			tagHost.textContent = '';
			if (ids.length) {
				tagHost.appendChild(secHead(t('rating.sec_tags')));
				var seg = document.createElement('div');
				seg.className = 'tile-dlg-seg ctile-rate-tags';
				seg.setAttribute('role', 'group'); seg.setAttribute('aria-label', t('rating.sec_tags'));
				ids.forEach(function (id) {
					var b = document.createElement('button');
					b.type = 'button'; b.className = 'tile-dlg-level'; b.dataset.tag = id;
					b.textContent = rateTagWord(form, id);
					b.addEventListener('click', function () {
						var i = st.tags.indexOf(id);
						if (i >= 0) st.tags.splice(i, 1); else st.tags.push(id);
						paint();
					});
					seg.appendChild(b);
				});
				tagHost.appendChild(seg);
			}
		}
		tagHost.querySelectorAll('.tile-dlg-level').forEach(function (b) {
			b.setAttribute('aria-pressed', st.tags.indexOf(b.dataset.tag) >= 0 ? 'true' : 'false');
		});
	}
	paint();

	// Clear finishes the dialog by its own cross, so there is one way out.
	if (clearBtn) clearBtn.addEventListener('click', function () {
		cleared = true;
		var x = body.closest('.modal-card') && body.closest('.modal-card').querySelector('.ui-close');
		if (x) x.click();
	});

	var closed = openBodyDialog(t(kind === 'file' ? 'rating.title_file' : 'rating.title'), body, { cardClass: 'rate-card' });
	if (adv.open) grow();
	closed.then(function () {
		var b = rateBurstFor(chat.id), ctx = rateCtx(chat, g);
		if (cleared) DaimondRatings.setDraft(b, h, { clear: true }, ctx);
		else if (st.s === null || rateSnap(st) === st0) { if (!b.drafts.size) _rateBurst.delete(chat.id); return; }
		else DaimondRatings.setDraft(b, h, { s: st.s, tags: st.tags, dims: st.dims, note: st.note }, ctx);
		rateArm(chat.id);
		if (pg.current === chat) mountRateControls();
	});
}

// ── The Rating tile ────────────────────────────────────────

function hhmm(ts) {
	if (!ts) return '';
	var d = new Date(ts);
	return ('0' + d.getHours()).slice(-2) + ':' + ('0' + d.getMinutes()).slice(-2);
}

/// The jump link: bring the rated answer's top to the top of the thread, moving no focus.
function rateJump(btn) {
	// A file's line jumps to its row by handle, an answer's to its tile by `data-mid`.
	var tile = btn.dataset.h
		? chatOutput.querySelector('.turn-file-row[data-h="' + cssEsc(btn.dataset.h) + '"]')
		: chatOutput.querySelector('.ctile[data-mid="' + cssEsc(btn.dataset.mid) + '"]');
	if (!tile) return;
	// The reader is acting on the thread, so a hold a render left running (it re-asserts
	// the live end for a second) must not drag them back down.
	hold(null);
	setScrollTop(chatOutput.scrollTop + tile.getBoundingClientRect().top - chatOutput.getBoundingClientRect().top);
}

/// The words for a tag id, or the id itself where the catalogue has none (a tag from a newer form).
function rateTagWord(form, id) {
	var tagKey = form ? form.keyOf(id) : 'rating.tag.' + id, word = t(tagKey);
	return word === tagKey ? id : word;
}

/// One `p.rate-line`: the score and the answer it is for, then the tags and the person's
/// own words. All text goes in through `textContent`. The translated sentence is split at
/// `{what}` so the link sits where each language puts it.
function rateLineEl(m, form) {
	var r = m.rating, file = DaimondRatings.isFile(r.h);
	// The target is the answer in the chat, or the row's record in a note in it; gone when neither is.
	var target = file ? (rateFileRecs().get(r.h) || null)
		: rateMsgById((pg.current && pg.current.messages) || [], DaimondRatings.midOf(r.h));
	var L = DaimondRatings.lineOf(m, target);
	var p = document.createElement('p');
	p.className = 'rate-line';
	var what;
	if (L.kind === 'file') {
		if (L.targetH !== null) {
			what = document.createElement('button');
			what.type = 'button'; what.className = 'rate-jump-link'; what.dataset.h = L.targetH;
			// From the Diamond's root, as the row shows it; the title keeps the whole path.
			var fo = DaimondRatings.fileOf(r.h);
			// The ellipsis is on an inner span, so the button does not clip its own tap overlay.
			var wt = document.createElement('span');
			wt.className = 'rate-jump-text';
			wt.textContent = t('rating.log_file', { path: DaimondProvenance.rel(L.path, fo ? fo.store : '') });
			what.appendChild(wt);
			what.title = L.path;
		} else {
			what = document.createTextNode(t('rating.log_file_gone'));
		}
	} else if (L.targetMid !== null) {
		what = document.createElement('button');
		what.type = 'button'; what.className = 'rate-jump-link'; what.dataset.mid = L.targetMid;
		what.textContent = t('rating.log_answer', { time: hhmm(target.ts) });
	} else {
		what = document.createTextNode(t('rating.log_gone'));
	}
	// The sentence is split at `{what}` (the link) and `{score}` (a figure, so it is in the mono face),
	// so each language puts them where it likes. A sentence without `{what}` still gets the link.
	var SEP = '\u0001', SCO = '\u0002', linked = false;
	var says = L.cleared ? t('rating.log_cleared', { what: SEP }) : t('rating.log_line', { score: SCO, what: SEP });
	says.split(/([\u0001\u0002])/).forEach(function (part) {
		if (part === SEP) { p.appendChild(what); linked = true; }
		else if (part === SCO) {
			var sc = document.createElement('span');
			sc.className = 'rate-score'; sc.textContent = L.score;
			p.appendChild(sc);
		}
		else if (part) p.appendChild(document.createTextNode(part));
	});
	if (!linked) p.appendChild(what);
	var labels = L.tags.map(function (id) { return rateTagWord(form, id); });
	if (labels.length) p.appendChild(document.createTextNode(' · ' + labels.join(' · ')));
	if (L.said) {
		p.appendChild(document.createTextNode(' · '));
		var q = document.createElement('span');
		q.className = 'rate-said'; q.textContent = t('rating.quote', { text: L.said });
		p.appendChild(q);
	}
	return p;
}

/// Draw one `rating_log` message: a line in the Rating tile of its burst, which is made
/// when the burst's first line arrives.
function appendRatingLine(m) {
	if (!window.DaimondRatings || !DaimondRatings.isRatingMsg(m)) return;
	var tiles = chatOutput.querySelectorAll('.ctile[data-t="rating"]');
	var tile = tiles.length ? tiles[tiles.length - 1] : null;
	if (!tile || tile.dataset.burst !== m.rating.burst || !isLastContent(tile)) {
		finalizeAssistant();
		tile = buildTile('rating', { who: t('rating.who'), expanded: true, ts: m.ts });
		tile.dataset.burst = m.rating.burst;
		var host = document.createElement('div');
		host.className = 'chat-msg-content';
		tile._body.appendChild(host);
		postToChat(tile);
	}
	tile._body.querySelector('.chat-msg-content').appendChild(rateLineEl(m, rateForm()));
}

/// A cheap per-message signature: its id and everything the drawing reads that could
/// change WITHOUT the id changing (content length, elision, outcome, the hand-off and
/// interruption marks, a fold's counts). Deliberately not a stringify of the whole
/// message -- the point is to diff a megabyte of transcript without touching a
/// megabyte, so only scalars and a length are read.
function msgSig(m) {
	if (!m) return '';
	var c = m.content == null ? '' : String(m.content);
	return (m.mid || '') + '#' + (m.role || '') + '#' + c.length
		+ '#' + (m.elided || 0) + '#' + (m.outcome || '') + '#' + (m.interrupted ? 1 : 0)
		+ '#' + (m.why || '') + '#' + (m.folded || 0) + '#' + (m.kept || 0)
		+ '#' + (m.ranOn || '') + '#' + (m.handoffFellBack ? 1 : 0) + '#' + (m.interject ? 1 : 0)
		// The hand-off REFUSAL marks (S-HAND #6): the placeholder's own `refused` (so the
		// seat note appears/clears) and the answer's `handoffRefused` (so its provenance
		// line survives a redraw). Both change the drawing without changing the id.
		+ '#' + (m.refused ? 1 : 0) + '#' + (m.handoffRefused ? 1 : 0) + '#' + (m.handoffBusy || '') + '#' + (m.handoffThread || '')
		+ '#' + (m.toDevice || '') + '#' + (m.claimedBy || '') + '#' + (m.seatNote || '')
		+ '#' + (m.name || '') + '#' + (m.callId || '') + '#' + (m.say ? JSON.stringify(m.say) : '');
}

export function sigsOf(messages) {
	var out = [];
	for (var i = 0; i < messages.length; i++) out.push(msgSig(messages[i]));
	return out;
}

/// Is `next` the already-drawn `prev` with zero or more messages appended, and nothing
/// in the drawn prefix changed? Only then is drawing the tail alone the same DOM as a
/// full rebuild would have produced. Any shortening, any change to a message already on
/// screen, or a middle insertion answers no, and the caller rebuilds.
function isAppendOf(prev, next) {
	if (next.length < prev.length) return false;
	for (var i = 0; i < prev.length; i++) if (prev[i] !== next[i]) return false;
	return true;
}

/// Draw one stored message as its tile(s). The SINGLE per-message drawing path, shared
/// by the full rebuild and the tail-only append, so the two cannot draw a message
/// differently. Every path reaches `postToChat`, which coalesces a run of same-type
/// tiles onto the box standing last -- so a tail drawn onto a thread whose last box is a
/// rollup groups exactly as a rebuild would have grouped it.
function drawHistoryMessage(m, i, arr) {
	// A message said into a running turn is a user message to the model and
	// not a turn of its own here, so it is drawn where it landed rather than
	// as the question that started something.
	if (m.role === 'user' && m.interject) appendInterjected(m.content);
	else if (m.role === 'user') {
		// A question already answered is drawn as answered (`askMarkAnswered`, inside).
		var ut = appendUserMessage(m.content, m.ts, m.prod, m.files, m.app === true);
		if (m.seatNote) drawSeatNote(ut, String(m.seatNote));
		// A runner turn's Files row names the files of his it changed (UNBLOCK-26).
		if (m.yours) appendYoursTile(m);
	}
	else if (m.role === 'assistant') {
		// A turn HANDED TO A PEER, still in flight: an empty `dispatched`
		// placeholder. It draws as its OWN hand-off tile (naming the device,
		// a live spinner, the §5 status and control) rather than as an empty
		// Daimond bubble with a footer under it — so a handed-off turn reads
		// as a tile in the flow from the moment it leaves, and the spinner is
		// visible for the whole wait (owner review 2026-09-05). Skipped once
		// the answer has merged (finished), so the tile does not sit spinning
		// beside the reply in the window before the placeholder is dropped.
		if (m.interrupted && m.why === 'dispatched' && !(m.content && m.content.trim())
			&& window.DaimondPeer && DaimondPeer.uiState) {
			appendDispatchedTile(m);
		} else {
			appendAssistantText(logRowText(m), m.ranOn, m.handoffFellBack, m);
			var div = curAsstDiv;
			finalizeAssistant();
			// A turn the tab died in the middle of: show what arrived, badge it, and offer to
			// run it again. The mark rides on the message so it survives further reloads.
			if (m.interrupted && div) markInterrupted(div, m);
		}
	}
	else if (m.role === 'error_log') { appendError(logRowText(m), m); }
	// A rating, drawn as one tile for its whole burst. Anything this build cannot read
	// (`isRatingMsg`) draws nothing, as a role it had never heard of would.
	else if (m.role === 'rating_log') { appendRatingLine(m); }
	// A chat turn's changed files, drawn from its records (display only, never sent to the model).
	else if (m.role === 'files_log') { appendFilesLog(m); if (m.yours) appendYoursTile(m); }
	// The app's own NEUTRAL voice -- a fan-out handover, drawn as a status line
	// rather than the red of an error. Its own role so a reload draws it that way.
	else if (m.role === 'note_log') { appendNote(m.content); }
	// THE COUNTS TRAVEL, so a reload draws the boundary where the live turn drew it.
	// A `vision_log` shares this drawing and is not a fold, so it passes none and gets
	// the plain notice -- see `appendCompacted`.
	else if (m.role === 'fold_log') { appendCompacted(m.content || '', m.folded, m.kept, m.ts); }
	else if (m.role === 'vision_log') { appendCompacted(logRowText(m) || '', undefined, undefined, m.ts); }
	else if (m.role === 'think_log') { appendThinking(m.content || '', false, m.ts, m.mid); }
	// A tool call that arrived as prose. Its own role rather than an assistant
	// message, because it is not the model's answer and must never be redrawn as
	// one -- which is precisely what happened on 2026-09-14.
	else if (m.role === 'leak_log') { appendLeak(m.content || '', m.ts); }
	// How the turn ended, redrawn from the record: a reload that dropped it
	// would leave a reader who had walked away with the same silence the
	// line exists to replace.
	else if (m.role === 'end_log') { appendEnding(m, !!arr && i === arr.length - 1); }
	// The runner's stand-in for the oldest rows of a frame it had to cut ("N steps not
	// shown"): a silent cut reads as a turn that did less than it did.
	else if (m.role === 'cut_log') { appendNote(logRowText(m)); }
	else if (m.role === 'tool_log') {
		// A record of a tool the agent ran. Display only: it is not sent
		// back to the model, which cannot replay a tool call it has no
		// call-id for.
		renderToolCall(m.name || '', m.args || '', m.callId || '', m.ts);
		// THE ONE PLACE PROSE IS STILL READ. A tool log stored before the outcome
		// was a field has the text and nothing else; one stored since carries it.
		renderToolResult(m.name || '', m.content || '',
			m.outcome || outcomeOfStoredText(m.content || ''), m.paused || '');
	}
}

// THE READER'S PLACE, AS A THING IN THE TRANSCRIPT RATHER THAN A NUMBER.
//
// `scrollTop` alone is only the reader's place while everything ABOVE the viewport
// keeps its height, and across an unrequested re-render it does not: the System band
// is rebuilt at the head of the thread, an image or a KaTeX font lands late, a tile
// two turns up gains a line. Restoring the number then puts the reader somewhere
// else and calls it the same place. So the place is recorded as a TILE and an
// offset -- the tile nearest the top of the viewport, and how far its top sits above
// or below that edge -- and restored by putting that tile back at that offset, which
// is the idiom `jumpBack` already uses to walk the questions.
//
// The key is the tile's turn number and its ordinal within that turn, because a
// rebuild draws new nodes and the old element is gone: `data-turn` is on every tile
// `tagTurn` drew, and the ordinal distinguishes the question from the answer beneath
// it. A tile the rebuild did not redraw (the turn was folded away) answers null and
// the caller falls back to the raw scrollTop, which is what it had before.
var ANCHOR_HOLD_MS = 1200;		// how long a restore keeps re-asserting itself
var _anchorHold = null;			// the live re-assert, cancelled by the next render

/// Where the reader is: the tile nearest the top of the viewport, and its offset
/// from that edge. Null when the thread holds no tile to anchor on.
function takeAnchor() {
	if (!chatOutput) return null;
	var or = chatOutput.getBoundingClientRect();
	var kids = chatOutput.children, seen = {};
	for (var i = 0; i < kids.length; i++) {
		var k = kids[i];
		if (!k.dataset || k.dataset.turn == null) continue;
		var turn = String(k.dataset.turn);
		seen[turn] = (seen[turn] || 0) + 1;
		var r = k.getBoundingClientRect();
		// The first tile whose bottom is still on screen is the one the reader is
		// reading from; everything before it is above the fold.
		if (r.bottom - or.top > 1) return { turn: turn, nth: seen[turn], off: r.top - or.top };
	}
	return null;
}

/// Put the anchored tile back where it was. True when it could be found.
function applyAnchor(a) {
	if (!a || !chatOutput) return false;
	var kids = chatOutput.children, n = 0;
	for (var i = 0; i < kids.length; i++) {
		var k = kids[i];
		if (!k.dataset || String(k.dataset.turn) !== a.turn) continue;
		if (++n !== a.nth) continue;
		// Measured, not computed from offsetTop: the thread is not necessarily the
		// offset parent. Same reading `jumpBack` takes.
		var d = k.getBoundingClientRect().top - chatOutput.getBoundingClientRect().top - a.off;
		if (Math.abs(d) > 0.5) setScrollTop(chatOutput.scrollTop + d);
		return true;
	}
	return false;
}

/// Hold the reader's place THROUGH the layout that has not happened yet.
///
/// A restore made the instant the tiles are drawn is made before the browser has
/// loaded the images in them, before KaTeX's fonts have swapped, and before an
/// embedded page has reported its height -- each of which changes the height of
/// something above the viewport and moves the reader. So `reassert` is run on the
/// next frame and for a short window afterwards, and the hold stops the moment the
/// reader touches the thread themselves: one that fought a real scroll would be the
/// same bug with better manners. Null cancels a hold and starts none.
function hold(reassert) {
	if (_anchorHold) { clearInterval(_anchorHold.iv); _anchorHold = null; }
	if (!reassert) return;
	var startedAt = Date.now(), scrollMark = _lastScrollAt;
	var h = { iv: 0 };
	var beat = function () {
		if (_lastScrollAt !== scrollMark || Date.now() - startedAt > ANCHOR_HOLD_MS) {
			clearInterval(h.iv);
			if (_anchorHold === h) _anchorHold = null;
			return;
		}
		reassert();
	};
	try { requestAnimationFrame(beat); } catch (e) { /* no rAF in this context */ }
	h.iv = setInterval(beat, 100);
	_anchorHold = h;
}

/// Hold the anchored tile where the render put it.
function holdAnchor(a) { hold(a ? function () { applyAnchor(a); } : null); }

/// Hold a reader who was at the live end ON it. The same need as `holdAnchor`
/// from the other side: the pin is written before the images and equations in
/// the tail have laid out, so a thread that grows afterwards leaves the reader
/// short of the end they were just pinned to.
function holdBottom() { hold(function () { setScrollTop(chatOutput.scrollHeight); }); }

/// Redraw the parts of the thread that are NOT the transcript: the queue box, the
/// System band, the permissions chip. Runs on every render -- full or append -- because
/// each can differ between two chats and the append path does not otherwise touch them.
function renderHistoryFurniture() {
	// A tile that awaited the reader may not any longer (a blocker cleared, a stamp aged).
	reconcileAwaiting();
	renderQueue();
	// The band belongs to the conversation on screen, and every part of it can differ between
	// two: a Diamond's fence is not a chat's, and a user may have rewritten one role prompt
	// and not the other.
	if (typeof renderWire === 'function') renderWire();
	// And the permissions chip, which carries the same kind of fact: whether THIS
	// conversation's commands have the network. Two chats side by side differ, and
	// the mark is on a button that does not otherwise redraw.
	if (window.DaimondHandMode && DaimondHandMode.refresh) DaimondHandMode.refresh();
	// Retry and Edit & resend, which belong to the LAST turn and so move with
	// every question asked. Here because this is the one call every render path
	// makes -- the rebuild, the append fast path, and the nothing-changed early
	// return, which still has furniture to put right.
	mountTurnActions();
	// The rating arrows on each answer, kept in step with the transcript.
	mountRateControls();
}

export function renderHistory(messages) {
	// KEEP THE READER'S PLACE across a re-render they did not ask for.
	//
	// renderHistory runs when a chat is opened, and also whenever the chats store
	// changes under the one already open -- a sync parcel arriving
	// (onChatsChangedElsewhere), another tab writing, a dispatch report landing, a
	// trashed chat restored. Rebuilding the thread resets the scroll (clearChat
	// empties it) and pins each turn to the bottom as it is drawn
	// (appendUserMessage), so before this every such change hauled a reader who had
	// scrolled up back down to the newest message on its own -- the transcript
	// "jumping around" when focus returned to the tab and a sync pull fired.
	//
	// Opening a DIFFERENT chat still lands at the bottom, where the conversation
	// is. Redrawing the SAME chat holds the reader exactly where they were, unless
	// they were already at the live end, in which case they stay pinned to it so a
	// turn added elsewhere comes into view. Both readings are taken BEFORE the
	// rebuild, while the old scroll state is still on screen.
	var sameChat = pg.current && pg.current.id && pg.current.id === _renderedChatId;
	var wasDown  = followsEnd();
	var keepTop  = chatOutput.scrollTop;
	// And the reader's place as a TILE, which survives a height change above the
	// viewport that the number cannot. See `takeAnchor`.
	var anchor   = sameChat ? takeAnchor() : null;

	// DO NOT REBUILD UNDER AN ACTIVE SCROLL. A store-driven re-render (a streamed
	// progress frame, another tab's write) that lands while the reader is mid-gesture
	// on a scrolled-up thread would clearChat (resetting scroll to the top) and then
	// write scrollTop back to hold their place -- and writing scrollTop mid-momentum
	// is what iOS reads as a yank, the "shaking" the reverted resume storm caused.
	// So when a SAME-CHAT change that is NOT a clean append arrives within a scroll's
	// settle window and the reader is not pinned to the live end, defer it a beat and
	// coalesce: when the gesture settles, the render runs and puts them back exactly.
	// A chat OPEN (`!sameChat`) is never deferred -- it is the reader's own action --
	// and an append is never deferred (it clears nothing and writes scrollTop only
	// when pinned), so the streaming common case stays immediate. A reader pinned to
	// the bottom is following the stream, not scrolling away, so it renders at once.
	var nextSigs = Array.isArray(messages) ? sigsOf(messages) : [];
	if (sameChat && !wasDown && Array.isArray(messages)
		&& (Date.now() - _lastScrollAt) < SCROLL_SETTLE_MS
		&& !isAppendOf(pg._renderedSigs, nextSigs)) {
		if (_deferredRenderTimer) clearTimeout(_deferredRenderTimer);
		_deferredRenderTimer = setTimeout(function () {
			_deferredRenderTimer = null;
			// The live messages, which may have grown again while the reader scrolled.
			if (pg.current && Array.isArray(pg.current.messages)) renderHistory(pg.current.messages);
		}, SCROLL_SETTLE_MS);
		return;
	}
	if (_deferredRenderTimer) { clearTimeout(_deferredRenderTimer); _deferredRenderTimer = null; }

	// THE APPEND FAST PATH. The same chat is on screen and the only change is turns
	// added on the end -- the common case behind every store-change nonce, a sync
	// pull, another tab's write, a landed dispatch. Draw the new tail onto the tiles
	// already standing (nothing cleared, the counters continue) rather
	// than clearing thousands of tiles and rebuilding every one. `drawHistoryMessage`
	// is the same door as the rebuild below, so the tail draws identically; the drawn
	// prefix is proven byte-for-byte unchanged by `isAppendOf`, so the result is the
	// same DOM. Falls through to the rebuild for a chat switch, a shortening, an edit,
	// or a middle insertion.
	// A DISPATCHED PLACEHOLDER WHOSE ANSWER HAS NOW MERGED forces the full rebuild
	// below: the append fast path would draw only the new tail (the answer) and leave
	// the placeholder's spinner tile -- drawn before the answer arrived -- standing.
	// The full rebuild re-runs `appendDispatchedTile`, which suppresses the spinner
	// beside a present reply (`dispatchedAnswerPresent`). Belt-and-braces to the
	// sync-path drop in `onChatsChangedElsewhere`, for any answer that merged without
	// dropping the placeholder (a chat not on screen at merge time, a legacy record).
	// AND A HAND-OFF TILE WHOSE STATE HAS MOVED since it was drawn (2026-09-25). A
	// report or a lease change moves the state without touching the transcript, so
	// the nothing-changed return below kept the old tile: "Sent to your other
	// devices" and its spinner stood beside a turn whose `done` report was in.
	var _staleDispatch = false, _staleAt = -1;
	if (sameChat && pg.current && Array.isArray(messages)) {
		for (var _sdi = 0; _sdi < messages.length; _sdi++) {
			var _sdm = messages[_sdi];
			if (!_sdm || _sdm.why !== 'dispatched' || (_sdm.content && _sdm.content.trim())) continue;
			if (dispatchedAnswerPresent(pg.current, _sdm) || handoffTileMoved(_sdm)) { _staleDispatch = true; _staleAt = _sdi; break; }
		}
	}
	// NOTHING CHANGED, SO NOTHING IS DRAWN AND NOTHING IS SCROLLED.
	//
	// Most pulls carry no news for the chat on screen: a parcel whose only
	// difference is the chunk index, another device's touch on a DIFFERENT chat, a
	// push acknowledged back. `onChatsChangedElsewhere` re-reads the open chat's
	// row unconditionally and calls this with an array that is message-for-message
	// what is already drawn -- and this used to fall into the append path, which
	// draws no tile but still re-pins a reader at the live end. That pin is where
	// the 2026-09-14 drift came from, and a transcript that did not change has no
	// reason to be re-pinned at all. The furniture is still redrawn: the queue, the
	// System band and the permissions chip belong to the chat and not to the
	// message list, and any of them can differ while the transcript does not.
	if (sameChat && _renderSynced && !_staleDispatch && Array.isArray(messages)
		&& nextSigs.length === pg._renderedSigs.length && isAppendOf(pg._renderedSigs, nextSigs)) {
		renderHistoryFurniture();
		return;
	}
	if (sameChat && _renderSynced && !_staleDispatch && Array.isArray(messages)) {
		// `nextSigs` was taken at the top of this function, before the defer guard.
		if (isAppendOf(pg._renderedSigs, nextSigs)) {
			_renderingHistory = true;
			loadTextFolds();
			for (var i = pg._renderedSigs.length; i < messages.length; i++) {
				drawHistoryMessage(messages[i], i, messages);
			}
			_renderingHistory = false;
			syncJumps();
			renderHistoryFurniture();
			// Pinned to the live end only if they were already there; otherwise put
			// back where the reader had it. NOT "left where it was": the tail was
			// drawn through `drawHistoryMessage`, and `appendUserMessage` pins the
			// thread to the bottom for every question it draws -- which is what a
			// live turn wants and is why a reader scrolled up used to be hauled
			// 600px down the moment another device's turn merged. Either way the
			// place is then HELD through the layout still to come: an image or an
			// equation in that tail lands after this line.
			if (wasDown) { setScrollTop(chatOutput.scrollHeight); holdBottom(); }
			else { if (!applyAnchor(anchor)) anchor = null; holdAnchor(anchor); }
			pg._renderedSigs = nextSigs;
			_renderedChatId = pg.current && pg.current.id ? pg.current.id : null;
			_renderSynced = true;
			return;
		}
	}

	// THE CHANGED TURN, NOT THE THREAD (UNBLOCK-47, 27 Oct). A handed-off turn's frame grows
	// the row the last frame ended on and adds the next: not an append, so every frame cleared
	// and redrew the whole thread, 558 messages on gilgamesh, until the page stopped. A change
	// confined to the last turns redraws from the question that opened the first of them, and
	// the turns above stand as drawn.
	if (sameChat && _renderSynced && Array.isArray(messages) && redrawFromTurn(messages, nextSigs, _staleAt)) {
		syncJumps();
		renderHistoryFurniture();
		if (wasDown) { setScrollTop(chatOutput.scrollHeight); holdBottom(); }
		else { if (!applyAnchor(anchor)) anchor = null; holdAnchor(anchor); }
		pg._renderedSigs = nextSigs;
		_renderedChatId = pg.current && pg.current.id ? pg.current.id : null;
		_renderSynced = true;
		return;
	}

	_renderingHistory = true;
	// THE SYSTEM BAND CROSSES THE REBUILD, because it is not part of the transcript
	// and it is at the HEAD of it. `clearChat` empties the thread, and `renderWire`
	// puts the band back only after an await into the engine -- so without this the
	// place is restored against a thread missing the band's height, and the reader
	// is moved by it when the band lands a frame later. Held out and put straight
	// back for the SAME chat; a chat SWITCH lands at the live end anyway and gets
	// the new chat's own band from `renderWire`.
	var heldWire = sameChat ? document.getElementById('wire-head') : null;
	if (heldWire) heldWire.remove();
	clearChat();
	// Before a single fold is drawn: which of them this chat's reader had open.
	loadTextFolds();
	if (!Array.isArray(messages)) { _renderingHistory = false; syncJumps(); pg._renderedSigs = []; _renderSynced = true; return; }
	messages.forEach(drawHistoryMessage);
	if (heldWire) chatOutput.insertBefore(heldWire, chatOutput.firstChild);
	_renderingHistory = false;
	syncJumps();
	renderHistoryFurniture();
	// Put the reader back where the head of this function measured them: at the
	// live end when they were already there or when this is a freshly opened chat,
	// otherwise exactly where they had scrolled to. The per-turn pin above is what
	// this overrides -- it fired for every user message the replay drew.
	if (!sameChat || wasDown) { setScrollTop(chatOutput.scrollHeight); holdBottom(); }
	else {
		// The number first, so a thread with nothing to anchor on (a transcript of
		// fold notices, a turn the rebuild dropped) lands where it always did, and
		// then the TILE, which is the reading that survives the band being rebuilt
		// above it and the images in it loading after it.
		setScrollTop(keepTop);
		if (!applyAnchor(anchor)) anchor = null;
		holdAnchor(anchor);
	}
	pg._renderedSigs = sigsOf(messages);
	_renderedChatId = pg.current && pg.current.id ? pg.current.id : null;
	_renderSynced = true;
}

/// Does `m` open a turn when drawn (`appendUserMessage`'s `_turn += 1`)?
function opensTurn(m) {
	return !!m && m.role === 'user' && !m.interject && !/^\[Daimond: this turn changed /.test(String(m.content || ''));
}

/// Redraw from the question opening the turn the first change in `messages` is in (or the
/// stale hand-off at `staleAt`), leaving the turns above it as drawn. The drawing state is
/// put back as that turn started (`_turnMarks`), so the result is what a whole rebuild draws.
/// False, with nothing touched, where it cannot be: no turn opens above the change, the
/// turn's question is not on screen, or a fold row whose marks stand above it has gone.
function redrawFromTurn(messages, nextSigs, staleAt) {
	var prev = pg._renderedSigs, n = Math.min(prev.length, nextSigs.length), i0 = 0;
	while (i0 < n && prev[i0] === nextSigs[i0]) i0++;
	if (staleAt >= 0 && staleAt < i0) i0 = staleAt;
	var sigKey = function (g) { var p = String(g).split('#'); return { role: p[1], key: p[0] || String(g) }; };
	var folds = {};
	for (var k = i0; k < nextSigs.length; k++) { var nk = sigKey(nextSigs[k]); if (nk.role === 'fold_log') folds[nk.key] = 1; }
	for (var r = i0; r < prev.length; r++) { var pk = sigKey(prev[r]); if (pk.role === 'fold_log' && !folds[pk.key]) return false; }
	var u = -1, turnN = 0;
	for (var i = 0; i < i0 && i < messages.length; i++) if (opensTurn(messages[i])) { u = i; turnN++; }
	if (u < 0 || turnN > _turn) return false;
	var mark = _turnMarks[turnN], head = null;
	var kids = chatOutput.children;
	for (var c = kids.length - 1; c >= 0; c--) {
		var kc = kids[c];
		if (kc.classList.contains('chat-msg-user') && kc.dataset.turn === String(turnN)) { head = kc; break; }
	}
	if (!mark || !head) return false;
	_renderingHistory = true;
	// Furniture stays, and so does a tile an earlier turn pinned last (`pinAwaiting`).
	for (var node = head, nx; node; node = nx) {
		nx = node.nextSibling;
		if (node === spinnerEl || node.id === 'chat-queued') continue;
		if (node.dataset && node.dataset.turn != null && +node.dataset.turn < turnN) continue;
		node.remove();
	}
	curAsstDiv = null; curAsstText = ''; liveThink = null; lastToolBlock = null;
	_askCard = mark.ask; _askJust = mark.askJust; _saidJust = mark.said; _handoffTurn = mark.handoff;
	_turn = turnN - 1; _jumpAt = -1; _turnMarks.length = turnN;
	loadTextFolds();
	for (var j = u; j < messages.length; j++) drawHistoryMessage(messages[j], j, messages);
	_renderingHistory = false;
	return true;
}

/// Is `m` the "not run" row? Read off its `notRun`, whatever its tag (SUHT-R F1). Its tag is the
/// one each old build routes as ONE turn retried as `-rt` under one lease, so an old page's Retry
/// cannot run it unrouted under a fresh id: a chat's row is `why: 'runner'` (the lost-turn tag),
/// a Diamond's `why: 'notrun'`, since the live build (4c94152fd) sends only a chat's `runner` row
/// to `retryTurn` and runs a Diamond's here under a fresh id (review MED-2). The rows SUHT wrote
/// before carry `why: 'notrun'` and no `notRun`.
function isNotRunRow(m) { return !!m && !!m.interrupted && (!!m.notRun || m.why === 'notrun'); }

/// Is `m` a lost turn's row, whose Retry asks the turn again as `lostRetryMid(m.iturn)`? A run
/// the runner lost, or a turn that ran nowhere ("not run").
export function isLostRow(m) { return !!m && !!m.interrupted && (m.why === 'runner' || isNotRunRow(m)); }

/// The prompt a "not run" row asks again: the one it carries, else its turn's own.
function notRunAsk(chat, m) {
	var ask = String((m && m.itext) || '');
	if (ask) return ask;
	((chat && chat.messages) || []).forEach(function (x) {
		if (x && x.role === 'user' && (x.mid === m.iturn || x.iturn === m.iturn)) ask = x.content || '';
	});
	return ask;
}

/// A lost row whose retry another device has CLAIMED: its `-rt` lease names another holder,
/// in any phase of its life (N1, review of STEER delta 1; D2-1, delta 2). Drawn "<device> is
/// doing this." with no Retry, as a handed-off turn's tile is, until the retraction arrives
/// and removes the row. A run that has ENDED there (`done`, or settled) still owns the turn:
/// the `-rt` id is single-use, so a Retry would stand down until the tombstone drains, a
/// dead button saying "not run" about an answered turn. Only a vacant, unsettled lease (the
/// busy give-back, or one aged out) draws Retry, which can win. The lease view's onChange,
/// on a write and at an expiry (D2-2), redraws the history. True when it drew.
function drawLostRowRunning(div, foot, m) {
	var rt = lostRetryMid(m.iturn);
	var who = '';
	try { who = peerLeaseClaimed(rt); } catch (e) { return false; }
	if (!who) return false;
	var name = '';
	try { name = who === '?' ? '' : runnerLabel(who); } catch (e) { name = ''; }
	var spin = document.createElement('span');
	spin.className = 'ti-spin';
	spin.innerHTML = '<span class="chat-spinner-dot"></span>'
		+ '<span class="chat-spinner-dot"></span><span class="chat-spinner-dot"></span>';
	var label = document.createElement('span');
	label.className = 'ti-label';
	label.textContent = name ? t('turn.peer_running_named', { name: name }) : t('turn.peer_running');
	foot.appendChild(spin); foot.appendChild(label);
	div.appendChild(foot);
	return true;
}

/// THE "NOT RUN" LINE SAYS WHY (NOTRUN-WHY; rulings §7 "Seat reasons are short"): "Not run ·"
/// and its cause's 2-4 word label, through the one renderer (`seatReason`), the sentence on
/// hover and, tapped, in its place; the runner's own words follow it where it gave them
/// (RUN-HIST E). A row with no cause keeps the plain words, its diagnostic on hover.
function drawNotRunReason(label, nr) {
	var r = seatReason(notRunWhyKey(nr));
	if (!r) {
		label.textContent = t('turn.not_run');
		if (nr && nr.why) label.title = String(nr.why);
		return;
	}
	var said = (nr.said && (nr.cause === 'refused' || nr.cause === 'keys' || nr.cause === 'oversize')) ? ' ' + String(nr.said) : '';
	var short = t('turn.not_run_because', { why: r.label }), whole = r.why + said;
	label.textContent = short;
	label.title = whole;
	label.dataset.why = String(nr.cause);
	label.setAttribute('role', 'button');
	label.setAttribute('tabindex', '0');
	label.setAttribute('aria-label', whole);
	label.setAttribute('aria-expanded', 'false');
	var flip = function (e) {
		if (e && e.type === 'keydown' && e.key !== 'Enter' && e.key !== ' ') return;
		if (e && e.preventDefault) e.preventDefault();
		var open = label.getAttribute('aria-expanded') !== 'true';
		label.textContent = open ? whole : short;
		label.setAttribute('aria-expanded', open ? 'true' : 'false');
	};
	label.addEventListener('click', flip);
	label.addEventListener('keydown', flip);
}

/// Badge a recovered assistant message as interrupted, with a Continue button that runs the
/// turn again. `m.iturn` groups every message of the interrupted turn; `m.itext` is the prompt
/// to re-run.
function markInterrupted(div, m) {
	div.classList.add('interrupted');
	var foot = document.createElement('div');
	foot.className = 'turn-interrupted';
	// A turn handed to a peer draws the §5 state machine, not the local
	// interrupted copy: its words and its control depend on the lease and the
	// report, which DaimondPeer.uiState decides (step 6).
	if (m.why === 'dispatched' && window.DaimondPeer && DaimondPeer.uiState) {
		renderDispatchedFooter(foot, m);
		div.appendChild(foot);
		return;
	}
	var label = document.createElement('span');
	label.className = 'ti-label';
	// A HAND-OFF THE DOOR TURNED AWAY BEFORE IT LEFT (SEND-UNHANDED): the turn ran nowhere,
	// and says so. Retry asks it again as a send is asked, through `retryTurn`'s lost route:
	// the switch decides where it runs, and every device's Retry names one turn, one lease.
	// Asked before the runner-lost row below, whose tag it shares (`isNotRunRow`).
	if (isLostRow(m) && drawLostRowRunning(div, foot, m)) return;
	if (isNotRunRow(m)) {
		label.className = 'ti-label lead-warn';
		drawNotRunReason(label, m.notRun);
		// RETRY FOLLOWS THE SWITCH; RUN HERE IS HIS CHOICE OF THIS DEVICE (NOTRUN-WHY 2). Both go
		// through the one fenced retry path (rulings l.16-18: one turn id, one lease); Run here
		// passes the switch by. A press disables both, so one tile asks once.
		var nb = document.createElement('button');
		nb.className = 'ti-continue';
		nb.textContent = t('turn.retry');
		var hb = document.createElement('button');
		hb.className = 'ti-continue';
		hb.textContent = t('turn.peer_runhere');
		var press = function (here) {
			return function () {
				if (nb.disabled) return;
				nb.disabled = hb.disabled = true;
				retryTurn(pg.current, m.iturn, notRunAsk(pg.current, m), here ? { lost: true, here: true } : { lost: true });
			};
		};
		nb.addEventListener('click', press(false));
		hb.addEventListener('click', press(true));
		foot.appendChild(label); foot.appendChild(nb); foot.appendChild(hb);
		div.appendChild(foot);
		return;
	}
	// A HANDED-OFF RUN THE RUNNER LOST (r545 F-C2-1): the device running it reloaded,
	// and the turn ended there as it stood rather than run again from its first round.
	// What it had done is above; Retry runs the whole turn afresh, a new turn, never a
	// continuation of a run whose state went with the reload.
	if (m.why === 'runner') {
		label.className = 'ti-label lead-warn';	// the glyph is drawn by the role; see `.lead-ok` in app.css
		label.textContent = runnerLostLabel(m);
		var rb = document.createElement('button');
		rb.className = 'ti-continue';
		rb.textContent = t('turn.retry');
		rb.addEventListener('click', function () {
			var ask = m.itext || '';
			if (!ask && pg.current) {
				(pg.current.messages || []).forEach(function (x) {
					if (x && x.role === 'user' && (x.mid === m.iturn || x.iturn === m.iturn)) ask = x.content || '';
				});
			}
			continueTurn(pg.current, m.iturn, ask, false, true);
		});
		foot.appendChild(label); foot.appendChild(rb);
		div.appendChild(foot);
		return;
	}
	// WHICH interruption. A turn that died on the road and a turn that died with the tab
	// are both interrupted and are not the same sentence, and until the road case existed
	// there was only one to say. A phone showing "the browser closed before this finished"
	// to somebody who had just walked out of wifi range is a small lie that makes the app
	// look like it does not know what happened to it.
	// Four literal calls rather than a key chosen in an expression: `dev/i18ncheck.mjs`
	// reads the key out of the source, and a key it cannot read is a key nothing can prove
	// exists in en.js -- where an absence is English for every language, silently.
	// A turn a pause caught part way (`brakeHeld`) says what to press to carry on.
	label.className = 'ti-label lead-warn';
	label.textContent = (m.why === 'offline'
		? (m.content ? t('turn.offline')      : t('turn.offline_early'))
		: m.why === 'paused'
			? (m.content ? t('turn.paused')   : t('turn.paused_early'))
			: (m.content ? t('turn.interrupted')  : t('turn.interrupted_early')));
	var btn = document.createElement('button');
	btn.className = 'ti-continue';
	// A DAIMON TURN IS RETRIED, not continued (D-20261010-22: "Retry now, Resume
	// later"). Continue re-enters through the chat path, which a Diamond's daimon
	// does not run on; Retry asks his question again through `runSteer`.
	if (pg.current && pg.current.diamondId && !m.why) {
		btn.textContent = t('turn.retry');
		btn.addEventListener('click', function () { continueTurn(pg.current, m.iturn, m.itext, false, true); });
		foot.appendChild(label); foot.appendChild(btn);
		div.appendChild(foot);
		return;
	}
	btn.textContent = t('turn.continue');
	btn.title = t('turn.continue_help');
	btn.addEventListener('click', function () { continueTurn(pg.current, m.iturn, m.itext); });
	foot.appendChild(label); foot.appendChild(btn);
	div.appendChild(foot);
}

/// Draw the §5 footer for a turn handed to a peer: the words for its current
/// state and the one control that state offers. The state is decided by the pure
/// `DaimondPeer.uiState` (peerUiStateFor); this only renders it. Literal `t()`
/// keys, so dev/i18ncheck.mjs can read every one out of the source.
function renderDispatchedFooter(foot, m) {
	var st = peerUiStateFor(m);
	if (st === 'done') return;			// the merged answer draws itself; no badge
	// BLOCKED -- the runner is stopped on something, and the tile says what and
	// offers the runner's own controls (owner ruling 2026-09-12). Drawn by its own
	// function and returned from here, so a blocker's words and buttons are one
	// place and the state machine below is untouched.
	if (st === 'blocked') { renderBlockerFooter(foot, m); return; }
	// A LIVE spinner for the whole in-flight wait, so a handed-off turn never
	// looks dead. Up while the turn is on the road or running on a peer — from
	// the moment it is dispatched, through the claim and the run, until the
	// answer syncs back (the placeholder is then dropped, or a report settles it
	// to parked/failed and the spinner rests). The dots are the SAME class the
	// thread's own turn spinner uses, so the two indications cannot drift and the
	// reduced-motion rest state applies to both (owner review 2026-09-05).
	if (st === 'dispatched' || st === 'claimed' || st === 'running' || st === 'awaiting-consent') {
		var spin = document.createElement('span');
		spin.className = 'ti-spin';
		spin.innerHTML = '<span class="chat-spinner-dot"></span>'
			+ '<span class="chat-spinner-dot"></span><span class="chat-spinner-dot"></span>';
		foot.appendChild(spin);
	}
	var label = document.createElement('span');
	label.className = 'ti-label';
	// The machine's NAME when we have it ("argonaut is doing this."), else the
	// generic wording ("Running on your other device."). The name comes from the
	// presence beat of whoever holds the lease.
	var holder = turnRunnerId(m.iturn);
	var name = runnerLabel(holder);
	if      (st === 'no-peer-awake') label.textContent = t('turn.peer_none');
	else if (st === 'ending')        { label.className = 'ti-label lead-warn'; label.textContent = t('turn.not_run'); }
	else if (st === 'claimed')       label.textContent = name ? t('turn.peer_claimed_named', { name: name }) : t('turn.peer_claimed');
	else if (st === 'running')       label.textContent = name ? t('turn.peer_running_named', { name: name }) : t('turn.peer_running');
	else if (st === 'awaiting-consent') {
		// The dispatch status stops lying: the runner is blocked on a live question
		// the user must answer, so it names the act and the machine rather than
		// sitting on "Sent to your other devices."
		var ask = _openAsk[String(m.iturn)] || null;
		var act = consentActPhrase(ask);
		label.textContent = name
			? t('turn.peer_consent_named', { name: name, act: act })
			: t('turn.peer_consent', { act: act });
	}
	else if (st === 'parked')        label.textContent = t('turn.peer_parked');
	else if (st === 'failed' || st === 'interrupted') {
		// INTERRUPTED, NOT REFUSED (UNBLOCK-7 F3): a runner that was cut off -- an aborted
		// report, a lease that expired under it, or a claim that went silent -- is named,
		// and the turn offered again. A hand-back (`error`) keeps "couldn't finish".
		// `interrupted` is the runner's own settled cut (check_f234 fix 1), always named.
		var iname = interruptedRunner(m, name, st === 'interrupted');
		if (iname != null) label.textContent = iname ? t('turn.peer_interrupted_named', { name: iname }) : t('turn.peer_interrupted');
		else label.textContent = pausedBack(m) || t('turn.peer_failed');
	}
	else {												// dispatched (pre-claim)
		// Name the CHOSEN target tentatively while the errand is out but unclaimed,
		// so the owner sees WHERE it is going -- "Sending to X…", present-progressive,
		// an intention not a claim, so seq 217's honesty holds (no past-tense "Handed
		// off to X" until a device has actually taken the lease). Generic only when no
		// target was named (a re-dispatch with no chosen peer).
		var tgt = handoffTargetLabel(m);
		label.textContent = tgt ? t('turn.peer_sending_named', { name: tgt }) : t('turn.peer_sent');
	}
	foot.appendChild(label);
	// The one control this state offers, from the pure table. A healthy hand-off
	// offers NOTHING (owner, D-20261009-23: no take back -- the person chose the seat
	// before sending). A stall or a failure offers RUN HERE; a parked turn a RE-RUN.
	// `DaimondPeer.dispatchControl` is the table; this owns the words and the wiring,
	// so a state can never draw a control the ruling forbids.
	var control = (window.DaimondPeer && DaimondPeer.dispatchControl)
		? DaimondPeer.dispatchControl(st, m)
		: (st === 'parked' ? 'rerun'
			: ((st === 'failed' || st === 'no-peer-awake') ? 'runhere' : ''));
	if (control === 'runhere' && st === 'failed' && interruptedRunner(m, name) != null) control = 'retry';
	if (control === 'retry') {
		var rt = document.createElement('button');
		rt.className = 'ti-continue';
		rt.textContent = t('turn.retry');
		// ASKED AGAIN AS A SEND IS (ruling D-20261010-22): the switch decides where it runs,
		// and the new turn is named from the cut one, so two devices' Retries are one turn
		// under one lease (`retryTurn`'s lost route, as a runner-lost row's Retry).
		rt.addEventListener('click', function () { retryTurn(pg.current, m.iturn, m.itext, { lost: true }); });
		foot.appendChild(rt);
	} else if (control === 'rerun') {
		var rr = document.createElement('button');
		rr.className = 'ti-continue';
		rr.textContent = t('turn.peer_rerun');
		rr.addEventListener('click', function () { reRunParked(pg.current, m.iturn, m.itext); });
		foot.appendChild(rr);
	} else if (control === 'runhere') {
		var rh = document.createElement('button');
		rh.className = 'ti-continue';
		rh.textContent = t('turn.peer_runhere');
		rh.addEventListener('click', function () { continueTurn(pg.current, m.iturn, m.itext, false, undefined, false); });
		foot.appendChild(rh);
	} else if (control === 'answeragain') {
		// An ask-card answer is never sent after the fact, even on a click: the
		// question is opened again instead, and answered beside its options.
		var aa = document.createElement('button');
		aa.className = 'ti-continue';
		aa.textContent = t('turn.peer_answeragain');
		aa.addEventListener('click', function () { answerAgain(pg.current, m.iturn); });
		foot.appendChild(aa);
	}
}

/// The runner a failed hand-off was interrupted on: its name, '' when it cannot be named,
/// or null when the failure was not an interruption (a hand-back, a refusal). `name` is
/// the live lease holder's, when there is one; `cut` says the state already knows it was one.
/// The words of a handed-off run the runner lost: "Interrupted on <device>" where the
/// row names the runner (`lostOn`, stamped where it wrote the row) and the name is
/// known here, else the unnamed sentence (check_f234 fix 6, I9).
function runnerLostLabel(m) {
	var who = (m && m.lostOn) ? deviceLabelFor(m.lostOn) : '';
	return who ? t('turn.peer_interrupted_named', { name: who }) : t('turn.runner_lost');
}

function interruptedRunner(m, name, cut) {
	var rep = peerReports[String(m && m.iturn)] || null;
	var lease = (window.DaimondLease && DaimondLease.record) ? DaimondLease.record(m.iturn) : null;
	cut = cut || (rep ? rep.status === 'aborted' : (!!(lease && lease.mode !== 'released') || !!m.claimedBy));
	if (!cut) return null;
	if (name) return name;
	var who = String((lease && lease.holder) || (rep && rep.by) || m.claimedBy || '');
	var nm = who ? deviceLabelFor(who) : '';
	return String(nm || m.toName || '');
}

/// The pause a runner turned this hand-off away for, in the words every door refuses
/// a pause with, or '' when it was not a pause (R53-U8b, QU8 Q3). The runner's report
/// names the node (`paused`); the tile said "couldn't finish" and its [Run here] was
/// the first anyone heard of a pause. [Run here] stays: it confirms the hold against
/// the mailbox, then runs, or says the same words again while the pause holds.
function pausedBack(m) {
	var rep = peerReports[String(m && m.iturn)] || null;
	if (!rep || rep.status !== 'error' || !rep.paused) return '';
	try { return DaimondModels.pauseError(String(rep.paused)).message; }
	catch (e) { return String(rep.why || ''); }
}

/// Draw the footer for a turn whose runner is BLOCKED: what stopped it, and the
/// same controls the runner itself is showing.
///
/// `DaimondPeer.blockerTileSpec` decides the SHAPE (which controls, and whether the
/// thing can be answered away from the runner at all); this owns the words, with a
/// literal `t()` per kind so `dev/i18ncheck.mjs` can read every key out of the
/// source. A kind this build does not know draws as a report with "Run here
/// instead", never as a button that would do nothing.
///
/// The three report-only kinds are report-only for a reason that is not a policy:
/// `requestPermission` needs a user gesture on the runner's own page, and a lock or
/// a refused provider key is a fact about that machine. Offering a remote "Allow"
/// for any of them would be a button that cannot work.
function renderBlockerFooter(foot, m) {
	var b = blockerFor(m.iturn);
	if (!b) { foot.appendChild(document.createTextNode('')); return; }
	var holder = (window.DaimondLease && DaimondLease.holder) ? DaimondLease.holder(m.iturn) : null;
	var name = holder ? deviceLabelFor(holder) : '';
	var spec = DaimondPeer.blockerTileSpec(b, name, selfDeviceId());

	// A live spinner for as long as the turn is held up, the same dots the thread's
	// own turn spinner uses: the turn has not stopped, it is waiting on a person.
	var spin = document.createElement('span');
	spin.className = 'ti-spin';
	spin.innerHTML = '<span class="chat-spinner-dot"></span>'
		+ '<span class="chat-spinner-dot"></span><span class="chat-spinner-dot"></span>';
	foot.appendChild(spin);

	var label = document.createElement('span');
	label.className = 'ti-label';
	var act = consentActPhrase({ tool: spec.tool, host: spec.host, about: spec.about, detail: spec.detail });
	var q   = spec.detail || t('egress.nothing');
	var permit = DaimondPeer.permitAsk(spec.kind);
	if (spec.kind === 'consent' || permit) {
		label.textContent = name ? t('turn.block_consent_named', { name: name, act: act })
			: t('turn.block_consent', { act: act });
	} else if (spec.kind === 'ask') {
		label.textContent = name ? t('turn.block_ask_named', { name: name, q: q })
			: t('turn.block_ask', { q: q });
	} else if (spec.kind === 'fsa') {
		label.textContent = name ? t('turn.block_fsa_named', { name: name }) : t('turn.block_fsa');
	} else if (spec.kind === 'lock') {
		label.textContent = name ? t('turn.block_lock_named', { name: name }) : t('turn.block_lock');
	} else if (spec.kind === 'provider') {
		label.textContent = name ? t('turn.block_provider_named', { name: name }) : t('turn.block_provider');
	} else {
		label.textContent = name ? t('turn.block_unknown_named', { name: name }) : t('turn.block_unknown');
	}
	foot.appendChild(label);

	// THE EXACT STRING being authorised, for a consent -- the same rule the dialog
	// keeps: what is being agreed to is not summarised.
	if ((spec.kind === 'consent' || permit) && spec.detail) {
		var quote = document.createElement('div');
		quote.className = 'ti-block-detail';
		quote.textContent = spec.detail;
		foot.appendChild(quote);
	}

	function btn(text, title, onClick) {
		var x = document.createElement('button');
		x.className = 'ti-continue';
		x.textContent = text;
		if (title) x.title = title;
		x.addEventListener('click', onClick);
		foot.appendChild(x);
		return x;
	}
	for (var i = 0; i < spec.controls.length; i++) {
		var c = spec.controls[i];
		if (c === 'grant') {
			btn(t('turn.block_allow'), '', function () { answerBlocker(m.iturn, b, 'allow'); });
		} else if (c === 'deny') {
			btn(t('turn.block_deny'), '', function () { answerBlocker(m.iturn, b, 'deny'); });
		} else if (c === 'choose') {
			// ONE BUTTON PER OPTION, in the model's own words. Answering an `ask`
			// from here is the same act the card performs on the runner -- choosing a
			// label -- so the answer travels as the choice and nothing is translated.
			spec.options.forEach(function (opt) {
				btn(String(opt), '', function () { answerBlocker(m.iturn, b, 'allow', String(opt)); });
			});
		} else {
			btn(t('turn.block_runhere'), t('turn.block_runhere_help'), function () {
				runBlockedTurnHere(pg.current, m.iturn, m.itext);
			});
		}
	}
	// NO TAKE-BACK on a blocked turn (owner take-back ruling 2026-09-17): a blocker
	// means a peer has CLAIMED and is running the turn, and take-back is pre-claim
	// only. The turn is answered here (the controls above) or run here, never revoked.
}

/// Has this dispatched turn's REAL answer already arrived? The merged reply is found
/// positionally, because a peer's answer syncs back with no `iturn` on it (runTurn
/// stamps only the interrupted branches) — so the answer that belongs to a dispatched
/// turn is the first non-empty, non-interrupted assistant message after its
/// placeholder and before the next question. Used to drop the placeholder and to stop
/// the hand-off chrome once the durable answer has landed.
///
/// A PROVISIONAL streamed row does NOT count (owner standing rule 2026-09-18): the
/// answer streams as provisional tiles WHILE the turn runs, and the placeholder's
/// chrome (the spinner) must stay until the durable answer merges. A bare `done`
/// report no longer counts either -- the report is a nudge, not the answer; dropping
/// the placeholder on it (before the answer was in the transcript) is what forced the
/// rebuild that lost the streamed tile.
export function dispatchedAnswerPresent(chat, m) {
	if (!chat || !chat.messages) return false;
	var msgs = chat.messages;
	// A merged answer may still carry the turn's iturn (the interrupted-then-
	// finished paths do stamp it); match that first, wherever it sits. Provisional
	// rows are skipped -- only the durable, merged copy counts.
	for (var k = 0; k < msgs.length; k++) {
		var a = msgs[k];
		if (a.role === 'assistant' && !a.interrupted && !a.provisional && a.content && a.content.trim()
			&& String(a.iturn) === String(m.iturn)) return true;
	}
	// Positional: from the placeholder to the next question, a real reply is this
	// turn's answer. A synthetic send-time `m` is not in the array (indexOf -1);
	// nothing has merged yet then, so this correctly finds nothing.
	//
	// A ROW TAGGED WITH ANOTHER TURN IS THAT TURN'S WHEREVER IT STANDS (HATE-3, as
	// `turnSpan`). A cut-in re-sent as the next turn is pushed while the turn before it
	// is still settling, and a merge orders by `ts`: that turn's answer, stamped by its
	// runner a moment later, sorted below this placeholder and was taken for this turn's.
	// The placeholder was dropped, the watch ended before the runner ran, and the reply
	// it then sent was never read.
	var i = msgs.indexOf(m);
	if (i < 0) return false;
	for (var j = i + 1; j < msgs.length; j++) {
		var mm = msgs[j];
		if (mm.role === 'user' && !mm.interject) break;		// the next turn began
		if (mm.iturn && String(mm.iturn) !== String(m.iturn)) continue;	// another turn's row
		if (mm.role === 'assistant' && !mm.interrupted && !mm.provisional && mm.content && mm.content.trim()) return true;
	}
	return false;
}

/// The device a dispatched placeholder names while it waits: the lease HOLDER
/// once a peer has claimed it, else the target this device dispatched TO (stored
/// on the placeholder at dispatch, before any lease exists), so the tile can say
/// "Handed off to argonaut" from the first instant rather than "…to a device".
export function handoffTargetLabel(m) {
	try {
		var holder = (window.DaimondLease && DaimondLease.holder) ? DaimondLease.holder(m.iturn) : null;
		// THIS DEVICE'S OWN CLAIM IS ITS FALLBACK, NOT THE TARGET (UNBLOCK-1 DISPATCH-FAIL):
		// read while a local run held the lease, the answer's provenance said "Ran here --
		// hand-off to <this device> didn't finish".
		if (holder && String(holder) !== String(selfDeviceId())) { var hn = deviceLabelFor(holder); if (hn) return hn; }
	} catch (e) { /* presence/lease not up */ }
	// A turn handed TO this device names no target from here: run here, it reached its
	// runner, so "hand-off to <this device>" is never its provenance (rig busy3, r567bs).
	if (m.toDevice && String(m.toDevice) === String(selfDeviceId() || '')) return '';
	if (m.toName) return String(m.toName);
	if (m.toDevice) { var dn = deviceLabelFor(m.toDevice); if (dn) return dn; }
	return '';
}

/// Is the hand-off tile drawn for the placeholder `m` in a state it is no longer in?
/// A tile that was never drawn (a turn already done, or its answer present) cannot
/// have moved.
function handoffTileMoved(m) {
	var tile = chatOutput && chatOutput.querySelector('.chat-msg-handoff[data-handoff-turn="'
		+ cssEsc(String(m.iturn || '')) + '"]');
	return !!tile && tile.dataset.handoffState !== peerUiStateFor(m);
}

/// The name to put on the LIVE hand-off tile header -- the device that has ACTUALLY
/// CLAIMED the turn (holds a live lease), or '' when none has. Unlike
/// `handoffTargetLabel` it does NOT fall back to the chosen/guessed target: a tile
/// must not say "Handed off to gilgamesh" while gilgamesh has taken no lease and may
/// never run it (owner report 2026-09-06). Until a real claim the header stays generic
/// and the footer says "Sent to your other devices".
function handoffClaimLabel(m) {
	var holder = turnRunnerId(m && m.iturn);
	return holder ? deviceLabelFor(holder) : '';
}

/// The name the footer gives runner `id`: a peer's from its presence beat ('' reads
/// generic), this device's from the roster. This device has no beat of its own, so
/// it read '' while the turn ran here: "Another device is picking this up"
/// (UNBLOCK-1 DISPATCH-FAIL).
function runnerLabel(id) {
	if (!id) return '';
	try {
		if (String(id) === String(selfDeviceId() || '')) return deviceLabelFor(id);
		return (window.DaimondPresence && DaimondPresence.name) ? (DaimondPresence.name(id) || '') : '';
	} catch (e) { return ''; }
}

/// Is a hand-off tile in display state `st` the state of a turn still running? Done,
/// failed and interrupted are how a turn ended, not how it is going.
function handoffLive(st) {
	return st !== 'done' && st !== 'failed' && st !== 'interrupted' && st !== 'ending' && st !== 'not-dispatched';
}

/// Draw a turn HANDED TO A PEER as its own hand-off tile, live for the whole
/// wait: a header naming the device, a spinner and the §5 status/control in the
/// body. This is what a handed-off turn looks like in the flow from the moment
/// it leaves this device until its answer syncs back — the tile the owner asked
/// for, with the in-progress spinner that was missing (owner review 2026-09-05).
///
/// `m` is the dispatched placeholder (or, at send time, a synthetic stand-in
/// carrying the same fields). Nothing is drawn once the answer has merged: the
/// merged reply draws its own quiet "Handed off to <device>" provenance tile
/// (see `appendHandoff`), and a spinning tile beside a finished answer would lie.
function appendDispatchedTile(m) {
	var st = peerUiStateFor(m);
	if (st === 'done') return;			// the merged answer draws itself
	// The answer may already be in the transcript while the placeholder still
	// stands (the parcel synced back before its report was collected): treat that
	// as done here too, so the spinner does not linger beside the reply.
	try { if (pg.current && dispatchedAnswerPresent(pg.current, m)) return; } catch (e) { /* draw it */ }
	// Name the runner ONLY once a real lease claim exists; until then the header is
	// generic and the footer carries "Sent to your other devices" (owner 2026-09-06).
	// The header names the CLAIMANT once a real lease exists ("Handed off to X"),
	// else the CHOSEN target tentatively ("Sending to X…") -- present-progressive, an
	// intention not a claim, so seq 217's honesty holds. Generic only when no target.
	var dl   = handoffClaimLabel(m);				// the real lease holder, or ''
	var tgt  = (dl || st === 'ending') ? '' : handoffTargetLabel(m);	// the chosen target, pre-claim
	var line = dl  ? tOr('chat.ran_on', 'Ran on {name}', { name: dl })
		: tgt ? t('turn.peer_sending_named', { name: tgt })
		:       tOr('chat.who_handoff', 'Hand-off');
	// ONE STATUS LINE WHILE IT RUNS, as a Here turn has (owner, Nancy run: "the double
	// "argonaut is on it", "argonaut is doing this" are redundant"). The footer's dots
	// and line carry every live state, so a live tile draws no header; a turn that
	// ended keeps it, over the footer that says how.
	var tile = buildTile('handoff', { expanded: true, who: line, ts: m.ts, head: !handoffLive(st) });
	tile.classList.add('chat-msg-handoff');
	// The turn this tile is for, and the state it was drawn in (`handoffTileMoved`).
	tile.dataset.handoffTurn = String(m.iturn || '');
	tile.dataset.handoffState = st;
	var foot = document.createElement('div');
	foot.className = 'turn-interrupted ti-handoff';
	renderDispatchedFooter(foot, m);
	tile._body.appendChild(foot);
	// CHROME ONLY (owner standing rule 2026-09-18). The hand-off tile is now the
	// header, spinner and footer -- transient chrome. The turn's answer is not drawn
	// here: it STREAMS into its own real transcript tiles as provisional messages
	// (`onProgressFrame` -> `applyProvisional`), which grow like a live local turn and
	// are never discarded. The flattened `.handoff-stream` text view this once held
	// was exactly the interim view that filled and was then lost.
	// WHAT HAPPENED TO THE SEAT, under the status, which the footer cannot say: a
	// refused hand-off, and a turn that found nobody and is running on this phone,
	// which needs the screen kept open.
	var note = seatTileNote(m, st);
	if (note) {
		var nd = document.createElement('div');
		nd.className = 'seat-note' + (note.warn ? ' seat-warn' : '');
		nd.textContent = note.text;
		if (note.why) nd.title = note.why;
		tile._body.appendChild(nd);
	}
	drawHandoffWorkers(tile, m.iturn);
	tagTurn(tile);
	// It is the running turn's state, so it stands last while the turn is live
	// (UNBLOCK-6), and awaits the reader while the runner is blocked on a question or
	// a consent. Settled, or its answer in, it goes back to the head of its turn.
	tile._progress = true;
	tile._awaits = function () {
		if (blockerFor(m.iturn)) return true;
		if (!handoffLive(peerUiStateFor(m))) return false;
		try { return !(pg.current && dispatchedAnswerPresent(pg.current, m)); } catch (e) { return true; }
	};
	postToChat(tile);
}

/// The seat's own line on a dispatched tile, or null when there is nothing to add.
///
/// A turn that reached NOBODY
/// (`no-peer-awake`) on a MOBILE device is the loud case: it is about to run here, and
/// here is the device that cannot be backgrounded without stalling it.
function seatTileNote(m, st) {
	if (!m) return null;
	// REFUSED (S-HAND #6). The relay turned the errand away (a 413, or a prompt larger
	// than the door), so it never reached a peer and the turn is running HERE. Said out
	// loud rather than left as a silent local run, with the status on the tooltip. A
	// re-dispatch clears `refused` (markTurnDispatched), so this shows only while the
	// refusal stands. A refusal the turn then ran here for is said once, on the
	// person's own message (`seatNote`), which outlives this tile.
	if (m.refused && !m.refused.noted) {
		return { text: t('seat.refused', { name: seatNameOf(m.toDevice, m.toName) }),
			why: String(m.refused.why || ''), warn: true };
	}
	if (st === 'no-peer-awake' && isMobileDeviceSelf()) {
		var plan = seatPlanNow();
		var why  = seatReason((plan && plan.why === 'runner-silent')
			? { k: 'runner_silent',
				vars: { name: (plan.runnerId && deviceLabelFor(plan.runnerId)) || t('devices.unknown') } }
			: { k: 'no_desktop' }).why;
		// One clause on the tile, the reason on its tooltip -- the seat switch's rule.
		return { text: t('seat.tile_local_mobile'), why: why, warn: true };
	}
	return null;
}

// ── A DIAMOND'S OWN FOLDER (HATE-7) ──
//
// An absolute path on its runner, where that Diamond's turns start: sent as the errand's
// `scope.root`, which the runner reads as the start directory (`errand_place`), the
// workspace staying its home. Choosing it never swaps the workspace, so a second Diamond
// keeps its own. Kept on this device, keyed by Diamond id, as `daimond-diamond-models` is.
var DIAMOND_FOLDER_KEY = 'daimond-diamond-folder';	// { diamondId: '/abs/path' }

function diamondFolder(id) {
	if (!id) return '';
	var all = readJson(DIAMOND_FOLDER_KEY, {}) || {};
	var f = all[id];
	return (typeof f === 'string' && f.charAt(0) === '/') ? f : '';
}

/// '' clears.
function setDiamondFolder(id, path) {
	if (!id) return;
	var all = readJson(DIAMOND_FOLDER_KEY, {}) || {};
	if (path) all[id] = path; else delete all[id];
	try { localStorage.setItem(DIAMOND_FOLDER_KEY, JSON.stringify(all)); } catch (e) { /* quota */ }
}

/// Does a runner that said where it may go reach `path`? Read from every runner row
/// carrying `reach` (gateway HATE-2); true while none does, the runner's own clamp then
/// being the only judge.
function folderInReach(path, presence) {
	var p = String(path || '').replace(/\/+$/, '') || '/';
	var roots = [];
	Object.keys(presence || {}).forEach(function (id) {
		var r = presence[id];
		if (r && Array.isArray(r.reach)) roots = roots.concat(r.reach);
	});
	if (!roots.length) return true;
	return roots.some(function (r) {
		var b = String(r || '').replace(/\/+$/, '');
		return p === (b || '/') || p.indexOf(b + '/') === 0;
	});
}

/// THE SCOPE A DISPATCHED TURN CARRIES (UNBLOCK-32 F2b): its holds, and, for a turn whose
/// folder is rooted here in a machine folder, that folder's NAME (`usr`, never a path),
/// as `{ root, holds }`, so the runner starts the turn in its own folder of that name and reads
/// relative paths from it. The plain array otherwise, as before; readers take either
/// (`DaimondPeer.scopeHolds`).
///
/// ONE PREDICATE with the switch (F2-FIX M1): the folder is sent exactly where
/// `chatNeedsFolder` makes the turn need one, a plain chat whose workspace holding is opened
/// in the folder as much as a Diamond's mark, so a runner seated for the folder starts in it.
///
/// A Diamond with its own folder (HATE-7) sends that absolute path instead, ahead of all.
function errandScope(chat, holds) {
	try {
		var own = (chat && chat.diamondId) ? diamondFolder(chat.diamondId) : '';
		if (own) return { root: own, holds: holds };
		if (chatNeedsFolder(chat)) {
			var r = DaimondMarksHere._core.rootOf(rootHere());
			if (r.kind === 'machine' && r.name) return { root: r.name, holds: holds };
		}
	} catch (e) {
		diag('dispatch scope', 'chat=' + (chat && chat.id) + ' ' + String((e && e.message) || e));
	}
	return holds;
}

/// The door itself, called only by `handOffTurn`, the entry: `st.marked` is set the
/// moment the turn's placeholder is written, so the entry can tell a refusal before it.
export async function dispatchToPeer(chat, turnId, promptText, scopePaths, opts, st) {
	diag('dispatch start', 'chat=' + (chat && chat.id) + ' turn=' + turnId
		+ (opts && opts.toName ? ' to=' + String(opts.toId || '').slice(0, 8) : ''));
	// A PERSON'S PAUSE HOLDS A HAND-OFF AS IT HOLDS A TURN RUN HERE (R2 QA, F2). This is
	// the one door every hand-off passes, so it is asked here, before anything is marked
	// or posted: a held turn leaves no placeholder and no errand. `paused` tells the
	// caller to answer it where the person is, as the local run would.
	var hold = turnHold(chat);
	if (hold) {
		diag('dispatch refused', 'turn=' + turnId + ' paused at ' + hold);
		return { ok: false, paused: true, node: hold, why: DaimondModels.pauseError(hold).message };
	}
	if (!window.DaimondPeer || !DaimondPeer.buildDispatch
		|| !window.DaimondPost || !DaimondPost.post
		|| !window.DaimondSync  || !DaimondSync.push) {
		return { ok: false, why: 'the peer transport is not available in this build' };
	}
	// ONLY TO A RUNNER THAT RUNS THE TURN'S SET (D-20261018-09 OR). Every hand-off comes
	// through here, so here the errand is addressed, and only to a device that has shown it
	// honours the model set the errand carries: one before the Models menu runs a following
	// chat on its own default and says nothing. Asked before anything is marked or posted,
	// in the same run as the election that named it; `unable` is answered by the entry: not run, with Retry.
	var runTo = String((opts && opts.runTo) || '');
	if (!honoursModelSet(runTo)) {
		diag('dispatch refused', 'turn=' + turnId + ' runner ' + (runTo ? runTo.slice(0, 8) : 'unnamed')
			+ ' has not shown it runs the model set');
		return { ok: false, unable: true, why: 'no runner here runs this turn on its models' };
	}
	var pause = null;
	try { if (window.DaimondPause) pause = DaimondPause.snapshot(); } catch (e) { pause = null; }
	// This device's stable id, for "waiting for <machine>" and so a peer never
	// claims its own dispatch. The PER-DEVICE id, not the account key: pairing
	// shares the key, so a key-derived `by` could not tell a device from its twin.
	var by = selfDeviceId();
	// The GLOBAL park count this dispatch inherits (0 on a first dispatch, the
	// carried total on a re-run of a parked turn), so the ≤MAX_PARKS respend bound
	// holds across devices.
	var parkCount = (opts && (opts.parkCount | 0)) || 0;
	// THE CHAT'S ENGINE AS IT STANDS BEFORE THE FENCE IS READ, because `errandFence` may drop
	// it and build another, which starts with no mark (U4).
	var heldApp = chat && chat.app;
	var fence = await errandFence(chat, turnId);
	var cleanDia = (opts && opts.diamondId) || (chat && chat.diamondId) || '';
	var dispatchOpts = {
		turnId: turnId,
		// The Diamond this chat belongs to (a daimon chat), so the runner services it
		// through `steer_crystal`. '' for an ordinary chat. Falls back to the chat's own
		// `diamondId` when the caller did not name one.
		diamondId: (opts && opts.diamondId) || (chat && chat.diamondId) || '',
		prompt: promptText,
		// The note the person's message took when it was sent, READ from that record. A
		// re-dispatch, a parked re-run and a recovery all come through here, and none
		// composes one: the model hears what the original send was going to tell it.
		pre: storedPre(chat, turnId),
		// And the Effort it was sent with, read the same way, so a handed-off turn thinks as
		// hard as the person asked when they sent it (D-20261014-08).
		effort: (function () { var e = storedEffort(chat, turnId); return e === null ? turnEffortOf(chat) : e; })(),
		// THE THREAD, taken from the chat as it stands now -- after `maybeAutoDispatch`
		// pushed this turn's user message, so the seed ends at the prompt itself.
		// Built by `buildDispatch` from this same chat; named here only so a caller
		// that has a reason to suppress it (`seed: false`) has somewhere to say so.
		seed:   (opts && opts.seed === false) ? false : undefined,
		// The model the turn runs on, as this device resolved it: the chat's own, or its
		// Diamond's (C3). The url is resolved by the peer from the provider (models.js).
		model:  errandModelOf(chat),
		scope:  errandScope(chat, scopePaths || (Array.isArray(chat.holds) ? chat.holds : [])),
		fence:  fence,
		// THE CHAT HAS READ NOTHING FROM OUTSIDE (U4 ERRAND-TAINT): sent only when that is so,
		// and never as false. The runner reads a missing `clean` as tainted, so it only narrows.
		clean:  errandClean(chat, cleanDia, heldApp) ? true : undefined,
		// THE PACKS THIS ACCOUNT HAS NOT BOUGHT (U13a PACK-CARRY), as this tab holds them: the
		// runner never hears `pushLocks`, and it reads a missing list as every pack locked.
		locked: errandLocked(),
		// THE LIMITS THIS PAGE WOULD RUN THE TURN UNDER (KT-2): the runner applies them, and hands
		// back an errand that carries none rather than guess the model's window.
		limits: errandLimits(chat),
		pause:  pause,
		dispatchedBy: by,
		// THIS device's posture goes with the turn: on the runner it is the asker's
		// word, the only posture that answers the turn's permits there (B-F1).
		auto:   autonomousPosture(),
		tried:  (opts && Array.isArray(opts.handedBack)) ? opts.handedBack : [],	// Q19
		parkCount: parkCount,
		pendingOnly: !!(opts && opts.pendingOnly),	// a mail trigger's turn (§16)
		// The removals no parcel has carried yet, so the errand need not wait on one
		// (UNBLOCK-1), and the device the switch elected, which alone takes the turn.
		// `runTo`, not the tile's `toId`: the tile names the starred nominee, while the
		// election may seat another desk (a nominee busy elsewhere), and a `to` naming
		// the nominee made the elected desk stand down and the nominee bounce the turn.
		gone:   msgTombsOwed(),
		to:     runTo,
	};
	// A THREAD IS NEVER FINGERPRINTED FROM AN UNLOADED CHAT (D2). Every hand-off --
	// a send, a re-dispatch, a parked re-run -- comes through here, so it is made
	// resident here; `buildDispatch` refuses one that is not, and nothing is marked.
	if (chat && chat._loaded === false) {
		try { await loadChatMessages(chat); } catch (e) { /* refused below */ }
	}
	// THE CONVERSATION TRAVELS (KT-4, binding 15): the engine session this page would restore,
	// its reach and its today line, taken once the chat is resident, so the runner's turn sends
	// the same history and the same blocks as this page's.
	dispatchOpts.session = errandSession(chat, turnId);
	dispatchOpts.reach   = await errandReach(dispatchOpts.diamondId);
	dispatchOpts.today   = errandToday();
	dispatchOpts.words   = await errandWordsFor(chat, runTo);
	dispatchOpts.prodBase = errandProdBase(chat, dispatchOpts.model);
	var plan;
	try { plan = DaimondPeer.buildDispatch(chat, dispatchOpts); }
	catch (e) {
		var whyB = String((e && e.message) || e);
		diag('dispatch refused', 'turn=' + turnId + ' ' + whyB);
		return { ok: false, why: whyB };
	}
	var t0 = (opts && opts.t0) || Date.now();		// turn-send origin, if the caller gave one
	// Carry the chosen target onto the mark, so the tile names the device before a
	// lease holder exists.
	if (opts && (opts.toId || opts.toName)) {
		plan.mark.toDevice = opts.toId || '';
		plan.mark.toName   = opts.toName || '';
	}
	// And the device the errand was elected to, whether or not the tile names it, so the
	// backstop does not hand the turn straight back to it (`electedTried`, R4b).
	if (opts && Array.isArray(opts.tried) && opts.tried.length) plan.mark.tried = opts.tried.slice();
	// A step-away hand-off (a turn already running here, handed on as the page went) is
	// marked so, since one its runner did not take is run here, not ended "not run".
	if (opts && opts.stepAway) plan.mark.stepAway = true;
	// And whether the runner is native (its presence row, as `honoursModelSet` reads it), so
	// the asker folds its figures into the totals on adoption (RT-C): a page runner's own
	// record carries them home.
	try {
		var prN = (window.DaimondPresence && DaimondPresence.snapshot && DaimondPresence.snapshot()) || {};
		if (runTo && prN[runTo] && prN[runTo].kind === 'runner') plan.mark.toNative = 1;
	} catch (e) { /* no presence: the adoption falls back on the answer's `ranOn` */ }
	// 1. MARK THE LOCAL TURN FIRST. The DURABLE `why:'dispatched'` placeholder --
	//    and, through `drawHistoryMessage`, its hand-off tile -- is written BEFORE
	//    the post, so a refused post is a TRANSCRIPT event a store-driven rebuild
	//    reproduces, not DOM chrome the rebuild wipes into an empty turn
	//    (D-20260918-27). It is a local write, so it does not reintroduce the seq-223
	//    flush wait: the errand is still posted ahead of the parcel PUSH below.
	markTurnDispatched(chat, plan.mark);
	if (st) st.marked = true;
	// The placeholder AS THE CHAT HOLDS IT NOW. Read again after every await: a sync
	// merge in that window (`mergeMessages`) replaces the object, and a refusal stamped
	// on the old one was lost with it (UNBLOCK-1 DISPATCH-FAIL).
	function placeholderNow() {
		var ms = chat.messages || [];
		for (var pmi = ms.length - 1; pmi >= 0; pmi--) {
			var pmm = ms[pmi];
			if (pmm && pmm.why === DaimondPeer.REASON_DISPATCHED && String(pmm.iturn) === String(turnId)) return pmm;
		}
		return null;
	}
	// A HAND-OFF REFUSED AFTER ITS MARK ENDS "NOT RUN", by one door for every refusal (an
	// unpostable prompt, a refused post). It used to run here at once (UNBLOCK-1
	// DISPATCH-FAIL, I9); the rulings (§1 l.17, rig law NR) say a turn the switch sent
	// never runs elsewhere: the placeholder is stamped with the refusal, and
	// `endHandOffNotRun` takes and settles the turn's lease (a post whose answer was lost
	// may still have landed), writes the "not run" row with Retry and drops the placeholder.
	function refuseAndEndNotRun(status, why, cause) {
		var ph = placeholderNow();
		if (!ph) return;
		ph.refused = { status: status | 0, why: why, ts: Date.now() };
		touchMsg(ph);
		try { touchChat(chat); persistChats(); } catch (e) { /* the record stands regardless */ }
		try { endHandOffNotRun(chat, ph, 'refused after the mark: ' + why, notRunCause(cause, ph.toDevice, ph.toName)); } catch (e) { /* backstop + recovery-on-return remain */ }
	}
	// 2. SEAL THE ERRAND, dropping the thread seed if the sealed envelope would not
	//    fit the relay. A large recent tail both DUPLICATES what a synced peer already
	//    holds and would 413 the whole hand-off; the errand is then re-sealed seedless
	//    and the runner reconstructs from the parcel (peerReconstruct) -- the
	//    documented fallback (§, `seed:null` = "pull the parcel as before").
	var tPost = Date.now();
	var sealed;
	try { sealed = await DaimondPeer.sealFittingErrand(chat, dispatchOpts, plan); }
	catch (e) {
		// The identity is locked or absent: the errand cannot be sealed and the turn
		// cannot be run locally either (a local run needs the same identity). The
		// durable placeholder stands, so `recoverInterrupted` picks the turn up on the
		// next unlock rather than it being lost.
		var whyS = 'the errand could not be sealed: ' + (e && e.message || e);
		diag('dispatch FAILED', 'turn=' + turnId + ' seal: ' + whyS);
		var placeholder = placeholderNow();
		if (placeholder) {
			placeholder.refused = { status: 0, why: whyS, ts: Date.now() };
			touchMsg(placeholder);
			try { touchChat(chat); persistChats(); if (ownsChat(chat)) renderHistory(chat.messages); } catch (e2) { /* the record stands regardless */ }
		}
		return { ok: false, why: whyS };
	}
	// THE SESSION CAN GO NO WAY (ERRAND-REF): over the 8 MB a hand-off carries (`size`), or
	// its chunks could not be put (`post`). Nothing was posted; the turn ends "not run" with
	// that cause, which NOTRUN-WHY draws ("Too large to hand off", with Run here).
	if (sealed.notRun) {
		var whyN = sealed.notRun === 'size' ? t('errand.session_too_large') : t('errand.session_unsent');
		diag('dispatch FAILED', 'turn=' + turnId + ' ' + sealed.notRun + ': ' + sealed.why);
		// NOTRUN-WHY's call site: fire/notrunwhy gives refuseAndEndNotRun its `cause`; until it
		// merges, the third argument is unread and the row keeps the plain "not run" words.
		refuseAndEndNotRun(0, whyN, sealed.notRun);
		return { ok: false, why: whyN, refused: true };
	}
	var body = sealed.body;
	// THE SESSION WENT AS A REFERENCE (KT-4b): a runner that cannot read it hands the turn
	// back `thread`, and the note says the chat was too big to send, not too long to take.
	if (sealed.sessionRef) {
		var phRef = placeholderNow();
		if (phRef && !phRef.overDoor) { phRef.overDoor = true; touchMsg(phRef); }
	}
	// 2a. AN UNPOSTABLE PROMPT (S-HAND #6). Even seedless, the errand is over the relay
	//     door -- the prompt alone is larger than the relay accepts (a shortened seed
	//     always fits by construction, so this is only ever the prompt). Posting would
	//     413, so do NOT post: stamp the durable placeholder refused and recover the turn
	//     LOCALLY at once (this device holds the chat), which tells the user why rather
	//     than retrying into a wall. No 413 round trips.
	function fitsPostDoor(env) {
		var len = String(env || '').length;
		if (window.DaimondWire && DaimondWire.fits) return DaimondWire.fits('post', len);
		if (window.DaimondPost && DaimondPost.fitsRelay) return DaimondPost.fitsRelay(len);
		return true;
	}
	if (!fitsPostDoor(body && body.envelope)) {
		var whyBig = t('errand.prompt_too_large');
		diag('dispatch FAILED', 'turn=' + turnId + ' unpostable: prompt over the relay door');
		refuseAndEndNotRun(0, whyBig, 'size');
		return { ok: false, why: whyBig, refused: true };
	}
	// 2b. THE ERRAND IS NEVER BEHIND THE PARCEL (UNBLOCK-1, D-20261013-02). A whole-
	//     account flush ahead of the post (7ae6427e for an unflushed removal, 448f951b for
	//     a dropped seed) outlasted the sender's 95 s backstop on a slow link, so the
	//     sender ran the turn itself and the errand landed late or never (13 Oct, four
	//     of six Life log hand-offs). What that flush bought now rides the errand: the
	//     removals as `gone`, which the runner leaves out of the thread it judges and
	//     runs, and the thread as `thread`, which a seedless runner already holding the
	//     conversation matches at once. A runner that lacks it waits on the parcel below
	//     or hands the turn back -- the documented fallback, never a stalled send.
	var seedDropped = !!sealed.seedDropped;
	// THE ERRAND IT WAS SENT AS goes on the placeholder before the post, so a report
	// that answers another errand of the same turn id is known for one (`otherErrandReport`).
	var phE = placeholderNow(), sentEid = String((sealed.plan && sealed.plan.fields && sealed.plan.fields.eid) || '');
	if (phE && sentEid && phE.eid !== sentEid) { phE.eid = sentEid; touchMsg(phE); }
	// 3. POST THE ERRAND. It carries the prompt, the model, the scope, the pause
	//    snapshot and (where it fit) the thread, so a peer that claims reads
	//    everything the turn needs without waiting for a parcel. `parcelVersion` is 0 on
	//    every dispatch -- the receiver reads that as "no target version" and its
	//    progress-based catch-up handles it.
	var res = await DaimondPost.post(body);
	if (!res || !res.ok) {
		// A REFUSED POST IS NOT A LOST TURN (the D-20260918-27 / 413 failure). Stamp
		// the durable placeholder with the refusal and run the turn HERE at once: this
		// device holds the chat, so the take-if-vacant lease makes the local run
		// money-safe and it carries the seq-207 "Ran here -- hand-off didn't finish"
		// provenance on completion. A post refusal is relay-wide -- the errand goes to
		// the account's OWN box, collected by any device -- so re-posting to another
		// desktop cannot succeed where this did not; local recovery is the terminating,
		// correct route (it is the same money-safe path the +95 s backstop takes).
		var whyR = (res && res.why) || 'the relay would not take the errand';
		diag('dispatch FAILED', 'turn=' + turnId + ' ' + whyR + ' status=' + (res && res.status | 0));
		refuseAndEndNotRun((res && res.status) | 0, whyR, 'post');
		return { ok: false, why: whyR, refused: true };
	}
	// (a) THE ERRAND POSTED, and WHAT IT WEIGHED. The seed count is named -- and a
	// dropped-because-too-large seed flagged -- so a thread that outgrew the door is
	// visible rather than inferred.
	var seedMsgs = (sealed.plan.fields.seed && sealed.plan.fields.seed.msgs) ? sealed.plan.fields.seed.msgs.length : 0;
	var goneN = (sealed.plan.fields.gone || []).length;
	diag('dispatch posted', 'turn=' + turnId + ' post=' + (Date.now() - tPost) + 'ms'
		+ ' send->posted=' + (Date.now() - t0) + 'ms seed=' + seedMsgs + 'msg'
		+ (seedDropped ? '(dropped:too-large)' : '') + '/'
		+ String((body && body.envelope) || '').length + 'B gone=' + goneN);
	// The lens sees the stage too, so "elected, then never posted" is read off the
	// feed rather than inferred (diag.md fix 3).
	dsEvent('handoff', {
		act:  'post',
		turn: String(turnId).slice(0, 24),
		to:   String(dispatchOpts.to || '').slice(0, 12),
		ms:   Date.now() - t0,
		seed: seedMsgs,
		drop: seedDropped ? 1 : 0,
		gone: goneN,
		b:    String((body && body.envelope) || '').length,
	});
	// 4. PUSH THE PARCEL, IN THE BACKGROUND. Everything the turn may reach for that
	//    the errand does not carry -- the workspace, the Diamonds, the models, the
	//    ledger -- and the durable copy of this turn's own prompt. When the seed was
	//    dropped this push is also what the runner reconstructs the thread from. Not
	//    awaited: the
	//    runner is not waiting for it, and neither should the person who sent the
	//    turn. Its cost is logged when it lands, so a slow parcel stays visible.
	var tFlush = Date.now();
	(async function () {
		var v = 0;
		try {
			// An unconfirmed flush logs v=0: its rounds already pushed, and the work it
			// could not land is owed, so the retry ladder carries it.
			var fl = DaimondSync.flush ? await DaimondSync.flush() : null;
			if (fl && fl.ok) { v = fl.version | 0; msgTombsShipped(tFlush); }
			else if (!DaimondSync.flush) await DaimondSync.push();
		} catch (e) {
			// NOT a dispatch failure any more. The errand is already on the relay and
			// carries the thread, so the turn runs; what is lost is only the durable
			// copy, which the next ordinary push sends.
			diag('dispatch parcel FAILED', 'turn=' + turnId
				+ ' push/flush threw after ' + (Date.now() - tFlush) + 'ms');
			dsEvent('handoff', { act: 'parcel', turn: String(turnId).slice(0, 24), ok: 0, ms: Date.now() - tFlush });
			return;
		}
		diag('dispatch parcel', 'turn=' + turnId + ' v=' + v
			+ ' flush=' + (Date.now() - tFlush) + 'ms (background, after the post)');
		dsEvent('handoff', { act: 'parcel', turn: String(turnId).slice(0, 24), ok: v > 0 ? 1 : 0, v: v, ms: Date.now() - tFlush });
	})();
	return { ok: true, turnId: turnId, parcelVersion: 0 };
}

// ── WHERE THE NEXT TURN WILL RUN ───────────────────────────
//
// The election was invisible. A turn left for another machine, or stayed here, and
// the only way to find out which was to send it and watch: nothing on screen said
// what the next send would do. On a phone that is not a cosmetic gap -- a turn that
// runs locally needs the app kept in the foreground and the screen awake, and the
// user can only plan for that if they are told BEFORE they commit to it (owner spec
// 2026-09-12). One line under the composer, written from the latest beats and
// redrawn on every presence change and nomination change.

/// The options the seat switch's decision is taken with: the SAME ones
/// `maybeAutoDispatch` passes, so the line cannot promise a seat the send would not
/// take. `selfMobile` is the extra -- the line needs to know whether running HERE is
/// something the user must act on.
function seatOpts(chat) {
	var c = chat || pg.current;
	return {
		selfId:         selfDeviceId(),
		isPhone:        isPhoneViewport(),
		selfMobile:     isMobileDeviceSelf(),
		preferredLabel: preferredWorkerLabel(),
		currentBuild:   fleetCurrentBuild(),
		nominatedId:    (typeof nominatedDeviceId === 'function') ? nominatedDeviceId() : '',
		globalDefault:  handoffWhenAway(),
		freshWindowMs:  DaimondPeer.DISPATCH_FRESH_MS,
		toggle:         (c && chatSeatHere(c)) ? false : null,
		needFolder:     chatNeedsFolder(c),
		runnerOnly:     true,
		provider:       electProvider(c),
		sources:        electSources(c),
		// A re-read did not land (a gateway restart): the map is unknown and seats nobody.
		presenceUnknown: !!(window.DaimondPresence && DaimondPresence.unknown && DaimondPresence.unknown()),
	};
}

/// The provider an election judges `chat` by: the one its turn will run on, which is the
/// one its errand carries (`errandModelOf`), not the stored pick. A chat that follows the
/// default stores `''` (U1c), and judged by that a native runner, which serves credits only
/// (peer.js recEngineOk), was never offered a default-following chat even with the default
/// on credits (QA-B #3). '' only when nothing resolves.
function electProvider(chat) {
	try { return chat ? String(errandModelOf(chat).provider || '') : ''; }
	catch (e) { return ''; }
}

/// Every source `chat`'s turn pays with, across its halves (OWNKEY §2.2): the turn's own,
/// its workers' and its images', as its errand carries them. A runner is offered only when
/// it can use each one (peer.js recEngineOk). [] only when nothing resolves.
function electSources(chat) {
	var m = null;
	try { m = chat ? errandModelOf(chat) : null; } catch (e) { m = null; }
	var out = [];
	[m, m && m.workers, m && m.images].forEach(function (h) {
		var p = (h && h.provider) ? String(h.provider) : '';
		if (p && out.indexOf(p) < 0) out.push(p);
	});
	return out;
}

/// Is this chat's folder ROOTED on this device (F4c, UNBLOCK-32): the real folder open
/// here, and a mark of its Diamond or a workspace holding of its own pressed in it? Then
/// the turn runs only where a folder is held too, since a runner with none reaches none
/// of it and a switch that offers one which then cannot do the turn is a fault (§1).
function chatNeedsFolder(chat) {
	// A Diamond naming its own folder (HATE-7) needs no workspace folder held at the runner.
	if (chat && chat.diamondId && diamondFolder(chat.diamondId)) return false;
	if (!chat || !selfHoldsFolder() || !window.DaimondMarksHere || !DaimondMarksHere.rootedHere) return false;
	try { return DaimondMarksHere.rootedHere(chat.diamondId || '', chat.id || '', rootHere()); }
	catch (e) { return false; }
}

// ── THE PERSON'S CHOICE, per chat (owner, D-20261009-23) ──
//
// "Here" pins a chat to the device it is sent from; the runner segment lets the
// runner take it. Sticky per chat and kept on this device: "Here" means this
// device, so another device's choice for the same chat is not this one's.
var SEAT_HERE_KEY = 'daimond-seat-here';		// { chatId: 1 } for chats pinned here

function seatHereMap() {
	try { return JSON.parse(localStorage.getItem(SEAT_HERE_KEY) || '{}') || {}; }
	catch (e) { return {}; }
}

/// Is `chat` pinned to run here?
function chatSeatHere(chat) {
	var id = chat && chat.id ? String(chat.id) : '';
	return !!id && !!seatHereMap()[id];
}

function setChatSeatHere(chat, here) {
	var id = chat && chat.id ? String(chat.id) : '';
	if (!id) return;
	var m = seatHereMap();
	if (here) m[id] = 1; else delete m[id];
	try { localStorage.setItem(SEAT_HERE_KEY, JSON.stringify(m)); } catch (e) { /* this session only */ }
}

/// The runner the "Here | <runner>" switch draws pressed for `chat` now, by its label, or ''
/// where it draws Here or no runner (`renderSeatSwitch` draws from the same `seatSwitchFor`).
///
/// THE PERSON'S CHOICE IS WHAT THE SWITCH DREW AT THE PRESS (rulings §1 l.9, l.18; SUHT-R
/// killrunner). Read once, at the press of Send or Retry and before any presence read can
/// redraw the switch, and carried to the send's end: a runner drawn then and gone by the
/// send-time read ends "not run" (`endSendNotRun`); a switch already drawing Here runs the
/// turn here. A runner that stopped being drawn before the press is not the person's choice:
/// it was remembered until they pressed Here, and every Retry after the runner died ended
/// "not run" behind a switch reading plain Here.
function seatDrawnRunner(chat) {
	var sw = seatSwitchFor(chat);
	if (!sw || sw.choice !== 'runner' || !sw.runner) return '';
	return deviceLabelFor(sw.runner.deviceId) || sw.runner.label || t('devices.unknown');
}

/// Put the "ran here" line on a person's message tile.
function drawSeatNote(tile, text) {
	if (!tile || !tile._body || !text) return;
	var el = document.createElement('div');
	el.className = 'seat-note seat-warn';
	el.textContent = text;
	tile._body.appendChild(el);
}

/// The name a seat note gives a device: its label, the name it was sent under, or
/// "unknown device". The status code behind a refusal stays on the tooltip.
function seatNameOf(id, name) {
	return (id && deviceLabelFor(id)) || (name ? String(name) : '') || t('devices.unknown');
}

/// The plan as it stands right now, or null when nothing can be said (no chat open,
/// the peer module not up, this device not yet identified).
function seatPlanNow() {
	try {
		if (!window.DaimondPeer || !DaimondPeer.seatPlan) return null;
		// A daimon chat now seats like any other: `renderSeatSwitch` draws "Runs on
		// <device>" for it, because a daimon turn dispatches. `seatOpts()` reads the
		// daimon chat's own toolsEnabled/runOnPeer, so the pure `seatPlan` decides it
		// the same way it decides a chat.
		if (!pg.current) return null;
		var o = seatOpts();
		if (!o.selfId) return null;
		o.queueOn = chatRunningOn(pg.current);	// as the send reads it
		var presence = turnPresence((window.DaimondPresence && DaimondPresence.snapshot()) || {});
		return DaimondPeer.seatPlan(pg.current, presence, o, Date.now());
	} catch (e) { return null; }
}

/// What the "Here | <runner>" switch reads for `chat`, from the options and presence the
/// send reads, or null. The switch draws it and a follow-up typed into a running turn
/// obeys it (`sendPressed`), so the two cannot disagree.
export function seatSwitchFor(chat) {
	try {
		if (!chat || !window.DaimondPeer || !DaimondPeer.seatSwitch) return null;
		var o = seatOpts(chat);
		if (!o.selfId) return null;
		// A runner busy with THIS chat is still offered: the send queues there (O3).
		o.queueOn = chatRunningOn(chat);
		// The presence the send reads (`maybeAutoDispatch`): a claim this device
		// sees on another chat makes the runner busy before its own beat says so.
		var presence = presenceWithLeaseBusy(turnPresence(
			(window.DaimondPresence && DaimondPresence.snapshot()) || {}), chat);
		return DaimondPeer.seatSwitch(chat, presence, o, Date.now());
	} catch (e) { return null; }
}

/// Does the switch name a runner for `chat`, so its next turn is the runner's and not this device's?
function seatNamesRunner(chat) {
	var sw = seatSwitchFor(chat);
	return !!(sw && sw.choice === 'runner' && sw.runner);
}

/// Draw (or hide) the "Here | <runner>" switch by the input box (owner, D-20261009-23,
/// restated 2026-10-11: "down near the input box where the users eyes are"). Cheap and idempotent: it reads the live
/// snapshot, takes the pure decision and sets two buttons, so it can be called on
/// every presence beat without thought.
var _seatWhyOpen = '';	// the reason (its key tail) whose sentence a tap has opened in place

export function renderSeatSwitch() {
	var box  = document.getElementById('seat-switch');
	var here = document.getElementById('seat-here');
	var run  = document.getElementById('seat-runner');
	if (!box || !here || !run) return;
	var sw = seatSwitchFor(pg.current);
	// SEATWHY: one line beside a plain "Here" when the nominated runner is held off by a
	// rule the person can act on -- it serves credits only, or it runs another engine.
	// SEAT-LABELS: the label beside the seat, the sentence on hover and, tapped, in its place.
	var why = document.getElementById('seat-reason');
	if (why) {
		var r = seatReason(seatWhyKey(sw));
		if (!r || r.k !== _seatWhyOpen) _seatWhyOpen = '';
		var open = !!r && _seatWhyOpen === r.k;
		why.textContent = r ? (open ? r.why : r.label) : '';
		why.title = r ? r.why : '';
		why.setAttribute('aria-label', r ? r.why : '');
		why.setAttribute('aria-expanded', open ? 'true' : 'false');
		why.dataset.why = r ? r.k : '';
		why.hidden = !r;
	}
	// R4: one timer, at the moment the runner stops counting as reachable on the beat
	// it has, so the switch already reads Here when the person sends. A beat, a claim
	// or a release redraws through its own event and re-arms it.
	armSeatSwitchTimer(sw && sw.runner ? sw.until : 0);
	// On a single-device account "Here" is the only place a turn could ever run, so
	// the switch would say nothing (CHAT-07/PH-06). `loadDevices()`, not
	// `collectDevices()`, which writes the roster on every call.
	if (!sw || (!sw.runner && Object.keys(loadDevices()).length <= 1)) {
		box.hidden = true;
		return;
	}
	var onRunner = sw.choice === 'runner';
	here.setAttribute('aria-pressed', onRunner ? 'false' : 'true');
	if (sw.runner) {
		run.textContent = deviceLabelFor(sw.runner.deviceId) || sw.runner.label || t('devices.unknown');
		run.title = run.textContent;	// whole, where the row cuts it short
		run.dataset.device = sw.runner.deviceId;
		run.setAttribute('aria-pressed', onRunner ? 'true' : 'false');
		run.hidden = false;
	} else {
		run.hidden = true;
		run.textContent = '';
		run.title = '';
		delete run.dataset.device;
	}
	box.hidden = false;
}

/// THE ONE SEAT-REASON RENDERER (SEAT-LABELS; owner, 25 Oct: "wtf is this ridiculously long
/// explanation?"): the reason `{ k, vars }` as its 2-4 word label, drawn beside the seat, and its
/// sentence, the hover title and the tap. `k` is the tail of a `seat.why_` key. Every seat reason
/// the page shows is read here and nowhere else, so none can bypass its label
/// (seatlabels.test.mjs holds every key to a label in every locale). Null for no reason.
export function seatReason(r) {
	if (!r || !r.k) return null;
	return { k: r.k, label: t('seat.label_' + r.k, r.vars), why: t('seat.why_' + r.k, r.vars) };
}

/// The switch's reason (SEATWHY, OWNKEY §5.2) as `{ k, vars }` for `seatReason`, or null when it
/// names none: the source the runner cannot use and why, the re-approval a passphrase change
/// needs, another engine (it updates itself), a page older than the runner, a legacy runner's
/// credits only, or a seating rule (SEATWHY-ALL).
function seatWhyKey(sw) {
	if (!sw || !sw.why) return null;
	var name = deviceLabelFor(sw.runnerId) || t('devices.unknown');
	var v = { name: name };
	switch (sw.why) {
		case 'runner-source':
			var M = window.DaimondModels;
			return { k: 'runner_source', vars: { name: name,
				provider: (M && M.providerName) ? M.providerName(sw.source) : String(sw.source || ''),
				reason:   t('seat.reach_' + (sw.reach || 'nokey')) } };
		case 'runner-rekey':		return { k: 'runner_rekey',		vars: v };
		case 'runner-engine':		return { k: 'runner_engine',		vars: v };
		case 'runner-credits-only':	return { k: 'runner_credits',		vars: v };
		case 'runner-silent':		return { k: 'runner_quiet',		vars: v };
		case 'runner-busy':		return { k: 'runner_busy',		vars: v };
		case 'runner-phone':		return { k: 'runner_phone',		vars: v };
		case 'runner-require':		return { k: 'runner_require',		vars: v };
		case 'runner-nosource':	return { k: 'runner_nosource',	vars: v };
		case 'runner-unchecked':	return { k: 'runner_unchecked',	vars: v };
		case 'page-old':			return { k: 'page_old',			vars: v };
		default:					return null;
	}
}

/// The switch's reason as its whole sentence, or ''.
function seatWhyText(sw) {
	var r = seatReason(seatWhyKey(sw));
	return r ? r.why : '';
}

// WHY A TURN DID NOT RUN (NOTRUN-WHY): a "not run" row's cause, the tail of its `seat.why_`
// key. A runner's hand-back cause by its own name, and the page's own: `size` (an errand over
// what the runner reads), `unable`, `gone`, `unclaimed`, `released`, `unchecked`, `post`. Three
// are a switch reason already and are said the same way.
var NOTRUN_KEYS = {
	'size':          'notrun_size',
	'door':          'notrun_door',
	'thread':        'notrun_thread',
	'models':        'notrun_models',
	'models-behind': 'notrun_models_behind',
	'refused':       'notrun_refused',
	'place':         'notrun_place',
	'busy':          'notrun_busy',
	'unable':        'notrun_unable',
	'gone':          'notrun_gone',
	'unclaimed':     'notrun_unclaimed',
	'released':      'notrun_released',
	'unchecked':     'notrun_unchecked',
	'post':          'notrun_post',
	'oversize':      'notrun_oversize',
	'abi':           'runner_engine',
	'limits':        'page_old',
	'keys':          'runner_rekey',
};

/// A "not run" cause as the row keeps it, `{ cause, to, name, said }`: the runner it was sent
/// to by id and by the name known now, and the runner's own words where it gave them. Null for
/// a cause this page has no words for, which leaves the row's plain "not run".
export function notRunCause(cause, to, name, said) {
	var c = String(cause || '');
	if (!NOTRUN_KEYS[c]) return null;
	var id = String(to || '');
	var nm = String(name || '') || (id ? deviceNameFor(id) : '');
	return { cause: c, to: id, name: nm, said: said ? String(said) : '' };
}

/// A "not run" row's reason (`m.notRun`) as `{ k, vars }` for `seatReason`, or null where it
/// names no cause (a row written before causes, or a throw), which keeps the plain words.
function notRunWhyKey(nr) {
	var k = nr && NOTRUN_KEYS[String(nr.cause || '')];
	if (!k) return null;
	var name = (nr.to ? deviceNameFor(nr.to) : '') || String(nr.name || '') || t('devices.another');
	return { k: k, vars: { name: name } };
}

/// The wasm's engine ABI as `[abi, min]`, from its one export `engine_abi()` (a Uint32Array
/// of two). A build that predates it, or answers anything but two whole numbers with the
/// min no higher than the abi, is legacy: `[0, 0]`.
function wasmEngineAbi(W) {
	var v = null;
	try { v = (W && typeof W.engine_abi === 'function') ? W.engine_abi() : null; } catch (e) { v = null; }
	if (!v || typeof v.length !== 'number' || v.length !== 2) return [0, 0];
	var abi = v[0], min = v[1];
	var whole = function (n) { return typeof n === 'number' && n >= 0 && n === Math.floor(n) && n <= 0xffffffff; };
	if (!whole(abi) || !whole(min) || min > abi) return [0, 0];
	return [abi, min];
}

/// The wasm's first runner ABI that stages his words home (`words_abi()`), 0 from a build that
/// predates it or answers anything but a whole number from 1.
function wasmWordsAbi(W) {
	var v = 0;
	try { v = (W && typeof W.words_abi === 'function') ? W.words_abi() : 0; } catch (e) { v = 0; }
	return (typeof v === 'number' && v >= 1 && v === Math.floor(v) && v <= 0xffffffff) ? v : 0;
}

/// THIS PAGE'S ENGINE ID (R5a, X12): the sha-256 of the wasm it runs, read back from
/// the cache the module was loaded from. A native runner is offered on the switch only
/// when the id stamped into it at its release build is this one; until it is known,
/// none is.
async function learnEngineId() {
	// THE ENGINE ABI (OWNKEY ABI-a) first, read from the wasm and guarded for a build that
	// predates it: 0 offers a runner by the legacy rule and writes no `abi`.
	if (window.DaimondPeer && DaimondPeer.setEngineAbi) {
		var ab = wasmEngineAbi(Wasm);
		DaimondPeer.setEngineAbi(ab[0], ab[1], wasmWordsAbi(Wasm));
		// The offer is decided again now the page's side is known: until this line every ABI
		// runner read "not checked yet" (SEAT-LABELS truth).
		renderSeatSwitch();
	}
	if (!window.DaimondPeer || !DaimondPeer.setEngineId || !(window.crypto && crypto.subtle)) return;
	var res = await fetch(new URL('../../pkg/oxedyne_daimond_bg.wasm' /* page-split: rebased */, import.meta.url), { cache: 'force-cache' });
	if (!res.ok) return;
	var d = new Uint8Array(await crypto.subtle.digest('SHA-256', await res.arrayBuffer()));
	var hex = '';
	for (var i = 0; i < d.length; i++) hex += (d[i] < 16 ? '0' : '') + d[i].toString(16);
	DaimondPeer.setEngineId(hex);
	renderSeatSwitch();
}

var _seatSwitchTimer = null;
function armSeatSwitchTimer(until) {
	if (_seatSwitchTimer) { clearTimeout(_seatSwitchTimer); _seatSwitchTimer = null; }
	if (!(until > 0)) return;
	_seatSwitchTimer = setTimeout(function () { _seatSwitchTimer = null; renderSeatSwitch(); },
		Math.max(0, until - Date.now()));
}

/// The person presses a segment: the choice is the chat's, before it is sent.
function chooseSeat(here) {
	if (!pg.current) return;
	setChatSeatHere(pg.current, here);
	renderSeatSwitch();
}
// page-split: install 56

/// What the composer's Effort step stands for: the chat's own Effort, or on a Diamond's face
/// the daimon's, which is the Diamond's own (one door, D-20261014-08 F2).
function effortHolder() {
	if (!pg.current) return null;
	if (pg.current.diamondId) {
		var m = diamondModel(pg.current.diamondId);
		return { diamond: pg.current.diamondId, provider: m.provider || '', model: m.model || '',
			effort: diamondEffort(pg.current.diamondId) };
	}
	// The pair in force, which is the default's for a chat that follows it (U1c).
	var r = window.DaimondModels && DaimondModels.resolve(pg.current.provider || '', pg.current.model || '');
	return { chat: pg.current, provider: r ? r.provider : (pg.current.provider || ''),
		model: r ? r.model : (pg.current.model || ''), effort: pg.current.effort || '' };
}

/// The step's ladder. A model that names its default stands at that level when the Effort is
/// '' (the level's own name, in muted ink); one that names none has a "Default" rung below.
function effortLadder(f) {
	return f.dflt ? f.levels.slice() : [''].concat(f.levels);
}

/// Draw (or hide) the Effort step in the composer row (D-20261014-08): how hard the next
/// turn on screen thinks, over its model's levels. Hidden for a model that lists none.
function renderEffortStep() {
	// The source names the same record's model, so whatever moves one moves the other.
	renderSourceSwitch();
	var box = document.getElementById('effort-step');
	var dn  = document.getElementById('effort-dn');
	var up  = document.getElementById('effort-up');
	var val = document.getElementById('effort-val');
	if (!box || !dn || !up || !val) return;
	var h = effortHolder(), f = null;
	if (h) {
		try { f = DaimondModels.effortsFor(h.provider, h.model); } catch (e) { f = null; }
	}
	if (!f || !f.levels || !f.levels.length) { box.hidden = true; return; }
	var steps = effortLadder(f);
	var i = Math.max(0, steps.indexOf(h.effort || f.dflt));
	var lvl = steps[i];
	var dflt = !h.effort;					// the model's own default, whatever it is named
	val.textContent = lvl ? t('tile.effort_' + lvl) : t('composer.effort_default');
	val.title = dflt ? (f.dflt ? t('tile.effort_default_named', { level: t('tile.effort_' + f.dflt) })
		: t('tile.effort_default')) : t('tile.effort_help');
	val.classList.toggle('is-default', dflt);
	dn.disabled = i <= 0;
	up.disabled = i >= steps.length - 1;
	box.hidden = false;
}

/// A press of − or +: the Effort moves one step, landing on the model's own default as ''.
///
/// NO ENGINE CALL HERE (F3). `runTurn` and `diamondApp` put the Effort on the engine at each
/// turn's start, and the engine reads it on every request, so a press while a turn runs would
/// change that turn's remaining rounds while its record kept the old level. It is the next
/// turn's.
function stepEffort(by) {
	var h = effortHolder();
	if (!h) return;
	var f = null;
	try { f = DaimondModels.effortsFor(h.provider, h.model); } catch (e) { return; }
	if (!f || !f.levels || !f.levels.length) return;
	var steps = effortLadder(f);
	var i = Math.max(0, steps.indexOf(h.effort || f.dflt));
	var j = Math.min(steps.length - 1, Math.max(0, i + by));
	if (j === i) return;
	var next = steps[j] === f.dflt ? '' : steps[j];
	if (h.diamond) {
		setDiamondEffort(h.diamond, next);
		// THE DIAMOND'S EFFORT TRAVELS on the record's own stamp, in every parcel round
		// (`adoptDiamondModel`). Never by touching the Diamond: that won a whole-Diamond race
		// and put another device's crystal edit off the head (check_f1 B1).
		bumpDiamonds();
	} else {
		h.chat.effort = next;
		// The model half, on its own stamp with the model it belongs to (U1c).
		touchChatModel(h.chat);
		persistChats();
	}
	renderEffortStep();
}
// page-split: install 57

/// Draw (or hide) the credit-source switch at the head of the composer row (OWNKEY SW-1): the
/// short name of what the chat on screen pays with, and whose choice it is in the tooltip.
function renderSourceSwitch() {
	var box = document.getElementById('source-switch');
	var btn = document.getElementById('source-btn');
	var nm  = document.getElementById('source-name');
	if (!box || !btn || !nm) return;
	if (!pg.current || !window.DaimondModels) { box.hidden = true; return; }
	var id = '';
	try { id = sourceOf(pg.current); } catch (e) { id = ''; }
	var name = sourceLabel(id);
	nm.textContent = name || t('astat.credits');
	var scope = t(pg.current.diamondId ? 'composer.source_this_diamond' : 'composer.source_this_chat');
	// The name whole, where the row cuts it short, over whose choice this is.
	btn.title = (name ? name + '\n' : '') + t('composer.source_help', { scope: scope });
	box.hidden = false;
}

// ── The source menu: the railhead menu, opened off the switch ──
var _sourceMenu = null;
function closeSourceMenu() {
	if (!_sourceMenu) return;
	_sourceMenu.remove(); _sourceMenu = null;
	document.removeEventListener('click', onSourceMenuOutside, true);
	DaimondLayers.done('sourcemenu');
	var btn = document.getElementById('source-btn');
	if (btn) btn.setAttribute('aria-expanded', 'false');
}
// The switch itself is left to its own click, which toggles: shut here in the capture phase,
// the menu would only be opened again by it.
function onSourceMenuOutside(e) {
	var btn = document.getElementById('source-btn');
	if (_sourceMenu && !_sourceMenu.contains(e.target) && !(btn && btn.contains(e.target))) closeSourceMenu();
}

/// List where this chat can pay from (`sourceMenuRows`): Daimond credits with the balance the
/// rail shows, each provider whose key opens here, and "Add a provider…". The current one is
/// ticked, and the head says whose choice it is.
function openSourceMenu(anchor) {
	if (_sourceMenu) { closeSourceMenu(); return; }		// a second press toggles it shut
	if (!pg.current || !window.DaimondModels) return;
	var chat = pg.current;
	var menu = document.createElement('div');
	menu.className = 'railhead-menu source-menu';
	menu.setAttribute('aria-label', t('composer.source'));
	var head = document.createElement('div');
	head.className = 'railhead-menu-head';
	head.textContent = t(chat.diamondId ? 'composer.source_this_diamond' : 'composer.source_this_chat');
	menu.appendChild(head);
	sourceMenuRows(chat).forEach(function (r) {
		var b = document.createElement('button');
		b.type = 'button';
		if (r.add) {
			var sep = document.createElement('div');
			sep.className = 'railhead-menu-sep';
			sep.setAttribute('role', 'separator');
			menu.appendChild(sep);
			b.className = 'railhead-menu-item';
			b.setAttribute('role', 'menuitem');
			b.textContent = t('composer.source_add');
			b.addEventListener('click', function () { closeSourceMenu(); openSettings('', true); });
			menu.appendChild(b);
			return;
		}
		b.className = 'railhead-menu-item lead-ok';	// the tick is drawn by the role, as the Chats menu's is
		b.setAttribute('role', 'menuitemradio');
		b.setAttribute('aria-checked', r.checked ? 'true' : 'false');
		var n = document.createElement('span');
		n.className = 'source-row-name';
		n.textContent = r.name;
		b.title = r.name;
		b.appendChild(n);
		if (r.balance) {
			// The rail's figure: the tag glyph beside the value, in his currency.
			var bal = DaimondI18n.fillPrices(document.createElement('span'), r.balance);
			bal.className = 'source-row-bal';
			b.appendChild(bal);
		}
		b.addEventListener('click', function () { closeSourceMenu(); if (!r.checked) pickSource(chat, r.id); });
		menu.appendChild(b);
	});
	_sourceMenu = menu;
	DaimondLayers.hang(menu, 'sourcemenu', closeSourceMenu, anchor);
	// Below the switch where there is room, else above it: on a desktop the row is the
	// composer's last line, near the foot of the window.
	var a = anchor.getBoundingClientRect();
	menu.style.left = Math.max(8, Math.min(a.left, window.innerWidth - menu.offsetWidth - 8)) + 'px';
	var below = a.bottom + 4 + menu.offsetHeight <= window.innerHeight - 8;
	menu.style.top = Math.max(8, below ? a.bottom + 4 : a.top - 4 - menu.offsetHeight) + 'px';
	anchor.setAttribute('aria-expanded', 'true');
	setTimeout(function () { document.addEventListener('click', onSourceMenuOutside, true); }, 0);
}

/// A pick in the source menu: `chat` (or its Diamond) moves to `to`, the model chip and the
/// Effort step redraw, and the one toast says which model it now runs on.
async function pickSource(chat, to) {
	if (!chat.diamondId && chat._generating) {
		await noticeDialog(t('tile.chat_model_busy_title'), t('tile.chat_model_busy'));
		return;
	}
	var out = switchChatSource(chat, to);
	if (!out) {
		// A source whose list was never asked for maps to nothing until it is.
		try { await DaimondModels.fetchModels(to); } catch (e) { /* said below */ }
		out = switchChatSource(chat, to);
	}
	if (!out) { toast(t('chat.no_key_start'), true); return; }
	var note = effortClearedNote(out.eff, out.after.provider, out.after.model);
	var said = sourceMovedPair(out);
	renderSessionList();
	if (chat.diamondId) {
		if (pg.currentDiamond && pg.currentDiamond.id === chat.diamondId) await refreshDiamondAfterChange();
		else await loadDiamonds();
		toast(t('tile.model_changed', said) + note);
	} else {
		// A pending chat that can now start, starts (CHAT-01).
		if (chat.status === 'pending' && pg.current === chat) renderPendingCentre(chat);
		toast(t('tile.chat_model_changed', said) + note);
	}
	renderEffortStep();
}
