		x.type = 'button';
		x.className = 'addbtn acard-x';
		x.title = t('common.close');
		x.setAttribute('aria-label', t('common.close') + ' ' + run.name);
		x.innerHTML = '<svg class="ic" viewBox="0 0 24 24" aria-hidden="true"><path d="M6 6l12 12M18 6L6 18"/></svg>';
