			name.className = 'files-name';
			name.textContent = '\u{1F4C1} ..';
			row.appendChild(name);
			row.tabIndex = 0;
			row.setAttribute('role', 'button');
			row.title = t('work.parent');
			row.setAttribute('aria-label', t('work.parent'));
